/* ===== VIEW: [dbo].[V_MapRTGBond1] ===== */
CREATE VIEW dbo.V_MapRTGBond1
AS
SELECT     BONDR, SUM(CASE BONDC WHEN '100' THEN CountContainer ELSE 0 END) AS '100', SUM(CASE BONDC WHEN '102' THEN CountContainer ELSE 0 END) AS '102', 
                      SUM(CASE BONDC WHEN '104' THEN CountContainer ELSE 0 END) AS '104', SUM(CASE BONDC WHEN '106' THEN CountContainer ELSE 0 END) AS '106', 
                      SUM(CASE BONDC WHEN '108' THEN CountContainer ELSE 0 END) AS '108', SUM(CASE BONDC WHEN '110' THEN CountContainer ELSE 0 END) AS '110', 
                      SUM(CASE BONDC WHEN '112' THEN CountContainer ELSE 0 END) AS '112', SUM(CASE BONDC WHEN '114' THEN CountContainer ELSE 0 END) AS '114', 
                      SUM(CASE BONDC WHEN '116' THEN CountContainer ELSE 0 END) AS '116', SUM(CASE BONDC WHEN '118' THEN CountContainer ELSE 0 END) AS '118', 
                      SUM(CASE BONDC WHEN '120' THEN CountContainer ELSE 0 END) AS '120', SUM(CASE BONDC WHEN '122' THEN CountContainer ELSE 0 END) AS '122', 
                      SUM(CASE BONDC WHEN '124' THEN CountContainer ELSE 0 END) AS '124', SUM(CASE BONDC WHEN '126' THEN CountContainer ELSE 0 END) AS '126', 
                      SUM(CASE BONDC WHEN '128' THEN CountContainer ELSE 0 END) AS '128', SUM(CASE BONDC WHEN '130' THEN CountContainer ELSE 0 END) AS '130', 
                      SUM(CASE BONDC WHEN '132' THEN CountContainer ELSE 0 END) AS '132'
FROM         dbo.V_MapRTGBond1Pre
GROUP BY BONDR
HAVING      (NOT (BONDR = 'G' OR
                      BONDR = 'T'))

GO
/* ===== VIEW: [dbo].[V_MapRTGBond2] ===== */
CREATE VIEW dbo.V_MapRTGBond2
AS
SELECT     BONDR, SUM(CASE BONDC WHEN '133' THEN CountContainer ELSE 0 END) AS [133], SUM(CASE BONDC WHEN '134' THEN CountContainer ELSE 0 END) AS [134], 
                      SUM(CASE BONDC WHEN '135' THEN CountContainer ELSE 0 END) AS [135], SUM(CASE BONDC WHEN '137' THEN CountContainer ELSE 0 END) AS [137], 
                      SUM(CASE BONDC WHEN '138' THEN CountContainer ELSE 0 END) AS [138], SUM(CASE BONDC WHEN '139' THEN CountContainer ELSE 0 END) AS [139], 
                      SUM(CASE BONDC WHEN '141' THEN CountContainer ELSE 0 END) AS [141], SUM(CASE BONDC WHEN '142' THEN CountContainer ELSE 0 END) AS [142], 
                      SUM(CASE BONDC WHEN '143' THEN CountContainer ELSE 0 END) AS [143], SUM(CASE BONDC WHEN '145' THEN CountContainer ELSE 0 END) AS [145], 
                      SUM(CASE BONDC WHEN '146' THEN CountContainer ELSE 0 END) AS [146], SUM(CASE BONDC WHEN '147' THEN CountContainer ELSE 0 END) AS [147], 
                      SUM(CASE BONDC WHEN '149' THEN CountContainer ELSE 0 END) AS [149], SUM(CASE BONDC WHEN '150' THEN CountContainer ELSE 0 END) AS [150], 
                      SUM(CASE BONDC WHEN '151' THEN CountContainer ELSE 0 END) AS [151], SUM(CASE BONDC WHEN '153' THEN CountContainer ELSE 0 END) AS [153], 
                      SUM(CASE BONDC WHEN '154' THEN CountContainer ELSE 0 END) AS [154], SUM(CASE BONDC WHEN '155' THEN CountContainer ELSE 0 END) AS [155], 
                      SUM(CASE BONDC WHEN '157' THEN CountContainer ELSE 0 END) AS [157], SUM(CASE BONDC WHEN '158' THEN CountContainer ELSE 0 END) AS [158], 
                      SUM(CASE BONDC WHEN '159' THEN CountContainer ELSE 0 END) AS [159], SUM(CASE BONDC WHEN '161' THEN CountContainer ELSE 0 END) AS [161], 
                      SUM(CASE BONDC WHEN '162' THEN CountContainer ELSE 0 END) AS [162], SUM(CASE BONDC WHEN '163' THEN CountContainer ELSE 0 END) AS [163], 
                      SUM(CASE BONDC WHEN '165' THEN CountContainer ELSE 0 END) AS [165], SUM(CASE BONDC WHEN '166' THEN CountContainer ELSE 0 END) AS [166], 
                      SUM(CASE BONDC WHEN '167' THEN CountContainer ELSE 0 END) AS [167], SUM(CASE BONDC WHEN '169' THEN CountContainer ELSE 0 END) AS [169], 
                      SUM(CASE BONDC WHEN '170' THEN CountContainer ELSE 0 END) AS [170], SUM(CASE BONDC WHEN '171' THEN CountContainer ELSE 0 END) AS [171], 
                      SUM(CASE BONDC WHEN '173' THEN CountContainer ELSE 0 END) AS [173], SUM(CASE BONDC WHEN '174' THEN CountContainer ELSE 0 END) AS [174], 
                      SUM(CASE BONDC WHEN '175' THEN CountContainer ELSE 0 END) AS [175], SUM(CASE BONDC WHEN '177' THEN CountContainer ELSE 0 END) AS [177], 
                      SUM(CASE BONDC WHEN '178' THEN CountContainer ELSE 0 END) AS [178], SUM(CASE BONDC WHEN '179' THEN CountContainer ELSE 0 END) AS [179], 
                      SUM(CASE BONDC WHEN '181' THEN CountContainer ELSE 0 END) AS [181], SUM(CASE BONDC WHEN '182' THEN CountContainer ELSE 0 END) AS [182], 
                      SUM(CASE BONDC WHEN '183' THEN CountContainer ELSE 0 END) AS [183], SUM(CASE BONDC WHEN '185' THEN CountContainer ELSE 0 END) AS [185]
FROM         dbo.V_MapRTGBond2Pre
GROUP BY BONDR
HAVING      (NOT (BONDR = 'G' OR
                      BONDR = 'T'))

GO
/* ===== VIEW: [dbo].[V_RG_CurrentOperator] ===== */
CREATE VIEW dbo.V_RG_CurrentOperator
AS
SELECT     CHE, MAX(LoginDate) AS LoginDate
FROM         dbo.RG_Log
WHERE     (OperatorID <> '444444444')
GROUP BY CHE

GO
/* ===== VIEW: [dbo].[V_ContainerUnloadRG] ===== */
CREATE VIEW dbo.V_ContainerUnloadRG
AS
SELECT     TOP (100) PERCENT dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      REPLACE(CONVERT(varchar, CAST(dbo.CO_Containers.NetoWeight AS money), 1), '.00', '') AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, 
                      dbo.CO_Containers.CarrierCode AS קו, CASE WHEN TB_Trucks.EquipmentNumber IS NULL THEN EntranceTruckID ELSE TB_Trucks.EquipmentNumber END AS משאית, 
                      dbo.CO_Containers.RecommendedLocationCode AS איתור, dbo.CO_Containers.WaittingTime AS המתנה, dbo.TC_HazardousSubstances.ClassificationClass AS UN, 
                      dbo.CO_Containers.AVDM, dbo.CO_Containers.EntranceDriverID
FROM         dbo.CP_Deal INNER JOIN
                      dbo.CO_Containers INNER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container ON 
                      dbo.CP_Deal.DealNumber = dbo.CO_Containers.DealNumber LEFT OUTER JOIN
                      dbo.TB_Trucks ON dbo.CO_Containers.EntranceTruckID = dbo.TB_Trucks.TruckID LEFT OUTER JOIN
                      dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode
WHERE     (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CO_Containers.EntranceForkliftDate IS NULL) AND 
                      (dbo.CO_Containers.EntranceDate >= CONVERT(DATETIME, '2018-04-01 00:00:00', 102)) AND (dbo.CO_Containers.EntranceTruckFirst <> '0' OR
                      dbo.CO_Containers.EntranceTruckFirst IS NULL) AND (dbo.CO_Containers.LocationCode IS NULL OR
                      dbo.CO_Containers.LocationCode = '') AND (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND (LEFT(dbo.CO_Containers.RecommendedLocationCode, 3) >= '100' AND 
                      LEFT(dbo.CO_Containers.RecommendedLocationCode, 3) <= '185' OR
                      LEFT(dbo.CO_Containers.RecommendedLocationCode, 3) IS NULL) AND (dbo.CO_Containers.EntranceDriverID IS NOT NULL) AND 
                      (dbo.CO_Containers.Terminal = 'ILCXQ') OR
                      (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CO_Containers.EntranceForkliftDate IS NULL) AND 
                      (dbo.CO_Containers.EntranceDate >= CONVERT(DATETIME, '2018-04-01 00:00:00', 102)) AND (dbo.CO_Containers.EntranceTruckFirst <> '0' OR
                      dbo.CO_Containers.EntranceTruckFirst IS NULL) AND (dbo.CO_Containers.LocationCode IS NULL OR
                      dbo.CO_Containers.LocationCode = '') AND (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND (dbo.CO_Containers.EntranceDriverID IS NOT NULL) AND 
                      (RTRIM(dbo.CO_Containers.RecommendedLocationCode) = '') AND (dbo.CO_Containers.Terminal = 'ILCXQ') OR
                      (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CO_Containers.EntranceForkliftDate IS NULL) AND 
                      (dbo.CO_Containers.EntranceDate >= CONVERT(DATETIME, '2018-04-01 00:00:00', 102)) AND (dbo.CO_Containers.EntranceTruckFirst <> '0' OR
                      dbo.CO_Containers.EntranceTruckFirst IS NULL) AND (dbo.CO_Containers.LocationCode IS NULL OR
                      dbo.CO_Containers.LocationCode = '') AND (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND (dbo.CO_Containers.EntranceDriverID IS NOT NULL) AND 
                      (dbo.CO_Containers.RTG <> 0) AND (dbo.CO_Containers.Terminal = 'ILCXQ')

GO
/* ===== VIEW: [dbo].[V_ContainerUnloadRTG3] ===== */
CREATE VIEW dbo.V_ContainerUnloadRTG3
AS
SELECT  TOP (100) PERCENT dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
               REPLACE(CONVERT(varchar, CAST(dbo.CO_Containers.NetoWeight AS money), 1), '.00', '') AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, dbo.CO_Containers.CarrierCode AS קו, 
               CASE WHEN TB_Trucks.EquipmentNumber IS NULL THEN EntranceTruckID ELSE TB_Trucks.EquipmentNumber END AS משאית, 
               dbo.CO_Containers.RecommendedLocationCode AS איתור, dbo.CO_Containers.WaittingTime AS המתנה, dbo.TC_HazardousSubstances.ClassificationClass AS UN, 
               dbo.CO_Containers.AVDM, dbo.CO_Containers.EntranceDriverID
FROM     dbo.CP_Deal INNER JOIN
               dbo.CO_Containers INNER JOIN
               dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container ON dbo.CP_Deal.DealNumber = dbo.CO_Containers.DealNumber LEFT OUTER JOIN
               dbo.TB_Trucks ON dbo.CO_Containers.EntranceTruckID = dbo.TB_Trucks.TruckID LEFT OUTER JOIN
               dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode
WHERE  (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CO_Containers.EntranceForkliftDate IS NULL) AND 
               (dbo.CO_Containers.EntranceDate >= CONVERT(DATETIME, '2018-04-01 00:00:00', 102)) AND (dbo.CO_Containers.EntranceTruckFirst <> '0' OR
               dbo.CO_Containers.EntranceTruckFirst IS NULL) AND (dbo.CO_Containers.LocationCode IS NULL OR
               dbo.CO_Containers.LocationCode = '') AND (dbo.CP_Deal.HandlingTypeCode = 'FR') AND (dbo.CO_Containers.EntranceDriverID IS NOT NULL) AND 
               (dbo.CO_Containers.Terminal = 'ILCXQ')

GO
/* ===== VIEW: [dbo].[V_Location_BOND_TOP] ===== */
CREATE VIEW dbo.V_Location_BOND1_TOP
AS
SELECT     TOP (100) PERCENT LEFT(LocationCode, 4) + MAX(SUBSTRING(LocationCode, 5, 1)) AS LocationCode, BlocCode
FROM         dbo.TB_Location
WHERE     (BlocCode = 'BOND1' OR
                      BlocCode = 'BOND2') AND (Container IS NOT NULL)
GROUP BY LEFT(LocationCode, 4), BlocCode
ORDER BY LEFT(LocationCode, 4)

GO
/* ===== VIEW: [dbo].[V_LocationCount] ===== */
CREATE VIEW dbo.V_LocationCount
AS
SELECT        LEFT(LocationCode, 4) AS LocationCodeL, MAX(SUBSTRING(LocationCode, 5, 1)) AS Count
FROM            dbo.TB_Location
WHERE        (BlocCode = 'BOND1' OR
                         BlocCode = 'BOND2') AND (Container IS NOT NULL) AND (Terminal = 'ILCXQ')
GROUP BY LEFT(LocationCode, 4)

GO
/* ===== VIEW: [dbo].[V_LocationCountRTG3] ===== */
CREATE VIEW dbo.V_LocationCountRTG3
AS
SELECT        LEFT(LocationCode, 4) AS LocationCodeL, MAX(SUBSTRING(LocationCode, 5, 1)) AS Count
FROM            dbo.TB_Location
WHERE        (BlocCode = 'BOND3') AND (Container IS NOT NULL) AND (Terminal = 'ILCXQ')
GROUP BY LEFT(LocationCode, 4)

GO
/* ===== VIEW: [dbo].[V_OrderForkLift] ===== */
CREATE VIEW dbo.V_OrderForkLift
AS
SELECT DISTINCT 
                      dbo.CP_Order.Container, dbo.CP_Order.DealNumber, dbo.CP_Order.DealNumberSub, ' *** ' + CONVERT(VARCHAR(8), dbo.CP_Order.TargetDate, 3) 
                      + '  ' + dbo.TB_WorkType.WorkTypeDesc + ' *** ' AS OrderDesc
FROM         dbo.CP_Order INNER JOIN
                      dbo.TB_WorkType ON dbo.CP_Order.WorkTypeCode = dbo.TB_WorkType.WorkTypeCode
WHERE     (dbo.CP_Order.PerformCode = 0) AND (dbo.TB_WorkType.ForkLiftUse = 1)

GO
/* ===== VIEW: [dbo].[V_RTG_App_ContainerMovement] ===== */
CREATE VIEW dbo.V_RTG_App_ContainerMovement
AS
SELECT     dbo.CO_Containers.EntranceForkliftDate AS תאריך, 'כניסה' AS תנועה, dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, 
                      dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, dbo.CP_Deal.HandlingTypeCode AS טיפול, dbo.HR_Emp.EmpName AS מלגזן, 
                      dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.EntranceForkliftNumber AS מלגזה
FROM         dbo.CO_ContainerProfile INNER JOIN
                      dbo.CO_Containers ON dbo.CO_ContainerProfile.Container = dbo.CO_Containers.Container INNER JOIN
                      dbo.HR_Emp ON dbo.CO_Containers.EntranceForkliftOperatorID = dbo.HR_Emp.EmpID RIGHT OUTER JOIN
                      dbo.TB_Drivers ON dbo.CO_Containers.EntranceDriverID = dbo.TB_Drivers.DriverID LEFT OUTER JOIN
                      dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber
WHERE     (dbo.CO_Containers.EntranceForkliftDate >= GETDATE() - 7) AND (dbo.CO_Containers.EntranceForkliftDate <= GETDATE())
UNION ALL
SELECT     TOP (100) PERCENT CO_Containers_1.ReleaseForkliftDate AS תאריך, 'יציאה' AS תנועה, CO_Containers_1.Container AS מכולה, 
                      CO_ContainerProfile_1.ContainerLength AS גודל, CO_ContainerProfile_1.ContainerTypeCode AS סוג, CP_Deal_1.HandlingTypeCode AS טיפול, 
                      HR_Emp_1.EmpName AS מלגזן, CO_Containers_1.LoadPortCode AS איתור, CO_Containers_1.ExitForkliftNumber AS מלגזה
FROM         dbo.CO_ContainerProfile AS CO_ContainerProfile_1 INNER JOIN
                      dbo.CO_Containers AS CO_Containers_1 ON CO_ContainerProfile_1.Container = CO_Containers_1.Container INNER JOIN
                      dbo.HR_Emp AS HR_Emp_1 ON CO_Containers_1.ExitForkliftOperatorID = HR_Emp_1.EmpID RIGHT OUTER JOIN
                      dbo.TB_Drivers AS TB_Drivers_1 ON CO_Containers_1.EntranceDriverID = TB_Drivers_1.DriverID LEFT OUTER JOIN
                      dbo.CP_Deal AS CP_Deal_1 ON CO_Containers_1.DealNumber = CP_Deal_1.DealNumber
WHERE     (CO_Containers_1.ReleaseForkliftDate >= GETDATE() - 7) AND (CO_Containers_1.ReleaseForkliftDate <= GETDATE())

GO
/* ===== VIEW: [dbo].[V_RTG3Load] ===== */

CREATE VIEW [dbo].[V_RTG3Load]
AS
SELECT     TOP (100) PERCENT dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      REPLACE(CONVERT(varchar, CAST(dbo.CO_Containers.NetoWeight AS money), 1), '.00', '') AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, 
                      dbo.CO_Containers.CarrierCode AS קו, CASE WHEN TB_Trucks.EquipmentNumber IS NULL THEN ExitTruckID ELSE TB_Trucks.EquipmentNumber END AS משאית, 
                      REPLACE(dbo.CO_Containers.LocationCode, '-', '') AS איתור, RIGHT(RTRIM(dbo.CO_Containers.LocationCode), 1) + '/' + CAST(dbo.V_LocationCountRTG3.Count AS char(1)) 
                      AS מיקום, dbo.CO_Containers.WaittingTimeExitDate AS המתנה, dbo.TC_HazardousSubstances.ClassificationClass AS UN, dbo.CO_Containers.AVDM, 
                      dbo.CO_Containers.ExitDriverID, 0 AS Type
FROM         dbo.CO_Containers INNER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container INNER JOIN
                      dbo.TB_Trucks ON dbo.CO_Containers.ExitTruckID = dbo.TB_Trucks.TruckID INNER JOIN
                      dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber INNER JOIN
                      dbo.V_LocationCountRTG3 ON LEFT(dbo.CO_Containers.LocationCode, 4) = dbo.V_LocationCountRTG3.LocationCodeL LEFT OUTER JOIN
                      dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode
WHERE     (dbo.CO_Containers.Terminal = 'ILCXQ') AND (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitGAteDate IS NULL) AND 
                      (dbo.CO_Containers.ExitDate IS NOT NULL) AND (dbo.CO_Containers.ReleaseForkliftDate IS NULL) AND (dbo.CO_Containers.DestinationDesc <> 'קונטרם') AND 
                      (dbo.CO_Containers.WaittingTimeExitDate < 30000) AND (dbo.CO_Containers.ExitTruckFirst <> '0') AND (dbo.CO_Containers.ReserveDate IS NULL) AND 
                      (dbo.CP_Deal.HandlingTypeCode <> 'DP')
UNION ALL
SELECT     TOP (100) PERCENT CO_Containers_1.Container AS מכולה, CO_ContainerProfile_1.ContainerLength AS גודל, CO_ContainerProfile_1.ContainerTypeCode AS סוג, 
                      REPLACE(CONVERT(varchar, CAST(CO_Containers_1.NetoWeight AS money), 1), '.00', '') AS משקל, CP_Deal_1.HandlingTypeCode AS קוד, 
                      CO_Containers_1.CarrierCode AS קו, CASE WHEN TB_Trucks_1.EquipmentNumber IS NULL 
                      THEN ReflectExitTruckID ELSE TB_Trucks_1.EquipmentNumber END AS משאית, REPLACE(CO_Containers_1.LocationCode, '-', '') AS איתור, 
                      RIGHT(RTRIM(CO_Containers_1.LocationCode), 1) + '/' + CAST(V_LocationCountRTG3_1.Count AS char(1)) AS מיקום, 
                      CO_Containers_1.WaittingTimeReflectExitDate AS המתנה, TC_HazardousSubstances_1.ClassificationClass AS UN, CO_Containers_1.AVDM, 
                      CO_Containers_1.ReflectExitDriverID AS ExitDriverID, 1 AS Type
FROM         dbo.CO_Containers AS CO_Containers_1 INNER JOIN
                      dbo.CO_ContainerProfile AS CO_ContainerProfile_1 ON CO_Containers_1.Container = CO_ContainerProfile_1.Container INNER JOIN
                      dbo.CP_Deal AS CP_Deal_1 ON CO_Containers_1.DealNumber = CP_Deal_1.DealNumber INNER JOIN
                      dbo.V_LocationCountRTG3 AS V_LocationCountRTG3_1 ON LEFT(CO_Containers_1.LocationCode, 4) = V_LocationCountRTG3_1.LocationCodeL INNER JOIN
                      dbo.TB_Trucks AS TB_Trucks_1 ON CO_Containers_1.ReflectExitTruckID = TB_Trucks_1.TruckID LEFT OUTER JOIN
                      dbo.TC_HazardousSubstances AS TC_HazardousSubstances_1 ON CO_Containers_1.UNCode1 = TC_HazardousSubstances_1.UNCode
WHERE     (CO_Containers_1.EntranceDate IS NOT NULL) AND (CO_Containers_1.DestinationDesc <> 'קונטרם') AND (CO_Containers_1.ReleaseForkliftDate IS NULL) AND 
                      (CO_Containers_1.ExitGAteDate IS NULL) AND (CO_Containers_1.Terminal = 'ILCXQ') AND (CO_Containers_1.ExitToReflectDate IS NOT NULL) AND 
                      (CP_Deal_1.HandlingTypeCode <> 'DP') AND (CO_Containers_1.WaittingTimeReflectExitDate < 300) AND (CO_Containers_1.ReturnFromReflectDate IS NULL OR
                      CO_Containers_1.ReturnFromReflectDate = '01/01/1900')

GO
/* ===== VIEW: [dbo].[v_RtgContainerData] ===== */
CREATE VIEW dbo.v_RtgContainerData
AS
SELECT        TOP (100) PERCENT dbo.CO_Containers.Container, dbo.CO_ContainerProfile.ContainerLength, dbo.CO_ContainerProfile.ContainerTypeCode, dbo.CP_Deal.HandlingTypeCode, dbo.CO_Containers.LocationCode, 
                         CAST(CAST(dbo.CO_Containers.NetoWeight AS int) AS varchar(5)) AS NetoWeight, CASE WHEN dbo.CO_Containers.UNCode1 IS NULL THEN '' ELSE RTRIM(dbo.CO_Containers.UNCode1) END AS UNCode, 
                         LTRIM(RTRIM(dbo.TC_Client.ShortClientName)) AS ShortClientName, CASE WHEN OrderDesc IS NULL THEN '' ELSE RIGHT(OrderDesc, 15) END AS OrderDesc, dbo.CP_Deal.Permit, 
                         CASE WHEN ContainerCapacity = 'EM' THEN 'ריק' ELSE 'מלא' END AS Expr1, dbo.CO_Containers.ShipingLineCode, dbo.CO_Containers.MarksNumbers
FROM            dbo.CO_Containers INNER JOIN
                         dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container INNER JOIN
                         dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber INNER JOIN
                         dbo.TC_Client ON dbo.CP_Deal.RecieveCommisionCode = dbo.TC_Client.ClientCode LEFT OUTER JOIN
                         dbo.V_OrderForkLift ON dbo.CO_Containers.Container = dbo.V_OrderForkLift.Container AND dbo.CO_Containers.DealNumber = dbo.V_OrderForkLift.DealNumber
WHERE        (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (CASE WHEN DATEDIFF(d, exitdate, getdate()) > 1 THEN exitdate ELSE exitgatedate END IS NULL) OR
                         (CASE WHEN DATEDIFF(d, exitdate, getdate()) > 1 THEN exitdate ELSE exitgatedate END IS NULL) AND (dbo.CO_Containers.RegisterDate IS NOT NULL)
ORDER BY dbo.CO_Containers.LocationCode DESC

GO
/* ===== VIEW: [dbo].[V_RTGLoad] ===== */
CREATE VIEW dbo.V_RTGLoad
AS
SELECT        TOP (100) PERCENT dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, REPLACE(CONVERT(varchar, 
                         CAST(dbo.CO_Containers.NetoWeight AS money), 1), '.00', '') AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, dbo.CO_Containers.CarrierCode AS קו, CASE WHEN TB_Trucks.EquipmentNumber IS NULL 
                         THEN ExitTruckID ELSE TB_Trucks.EquipmentNumber END AS משאית, REPLACE(dbo.CO_Containers.LocationCode, '-', '') AS איתור, RIGHT(RTRIM(dbo.CO_Containers.LocationCode), 1) 
                         + '/' + CAST(dbo.V_LocationCount.Count AS char(1)) AS מיקום, dbo.CO_Containers.WaittingTimeExitDate AS המתנה, dbo.TC_HazardousSubstances.ClassificationClass AS UN, dbo.CO_Containers.AVDM, 
                         dbo.CO_Containers.ExitDriverID, 0 AS Type
FROM            dbo.CO_Containers INNER JOIN
                         dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container INNER JOIN
                         dbo.TB_Trucks ON dbo.CO_Containers.ExitTruckID = dbo.TB_Trucks.TruckID INNER JOIN
                         dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber INNER JOIN
                         dbo.V_LocationCount ON LEFT(dbo.CO_Containers.LocationCode, 4) = dbo.V_LocationCount.LocationCodeL LEFT OUTER JOIN
                         dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode
WHERE        (dbo.CO_Containers.Terminal = 'ILCXQ') AND (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitGAteDate IS NULL) AND (dbo.CO_Containers.ExitDate IS NOT NULL) AND 
                         (dbo.CO_Containers.ReleaseForkliftDate IS NULL) AND (dbo.CO_Containers.DestinationDesc <> 'קונטרם') AND (dbo.CO_Containers.WaittingTimeExitDate < 30000) AND (dbo.CO_Containers.ExitTruckFirst <> '0') AND 
                         (dbo.CO_Containers.ReserveDate IS NULL) AND (dbo.CP_Deal.HandlingTypeCode <> 'DP')
UNION ALL
SELECT        TOP (100) PERCENT CO_Containers_1.Container AS מכולה, CO_ContainerProfile_1.ContainerLength AS גודל, CO_ContainerProfile_1.ContainerTypeCode AS סוג, REPLACE(CONVERT(varchar, 
                         CAST(CO_Containers_1.NetoWeight AS money), 1), '.00', '') AS משקל, CP_Deal_1.HandlingTypeCode AS קוד, CO_Containers_1.CarrierCode AS קו, CASE WHEN TB_Trucks_1.EquipmentNumber IS NULL 
                         THEN dbo.CO_ContainersReflect.ReflectExitTruckID ELSE TB_Trucks_1.EquipmentNumber END AS משאית, REPLACE(CO_Containers_1.LocationCode, '-', '') AS איתור, RIGHT(RTRIM(CO_Containers_1.LocationCode), 1) 
                         + '/' + CAST(V_LocationCount_1.Count AS char(1)) AS מיקום, CO_Containers_1.WaittingTimeReflectExitDate AS המתנה, TC_HazardousSubstances_1.ClassificationClass AS UN, CO_Containers_1.AVDM, 
                         dbo.CO_ContainersReflect.ReflectExitDriverID AS ExitDriverID, 1 AS Type
FROM            dbo.CO_Containers AS CO_Containers_1 INNER JOIN
                         dbo.CO_ContainerProfile AS CO_ContainerProfile_1 ON CO_Containers_1.Container = CO_ContainerProfile_1.Container INNER JOIN
                         dbo.CP_Deal AS CP_Deal_1 ON CO_Containers_1.DealNumber = CP_Deal_1.DealNumber INNER JOIN
                         dbo.V_LocationCount AS V_LocationCount_1 ON LEFT(CO_Containers_1.LocationCode, 4) = V_LocationCount_1.LocationCodeL INNER JOIN
                         dbo.CO_ContainersReflect ON CO_Containers_1.Container = dbo.CO_ContainersReflect.Container AND CO_Containers_1.Manifest = dbo.CO_ContainersReflect.Manifest INNER JOIN
                         dbo.TB_Trucks AS TB_Trucks_1 ON dbo.CO_ContainersReflect.ReflectExitTruckID = TB_Trucks_1.TruckID LEFT OUTER JOIN
                         dbo.TC_HazardousSubstances AS TC_HazardousSubstances_1 ON CO_Containers_1.UNCode1 = TC_HazardousSubstances_1.UNCode
WHERE        (CO_Containers_1.EntranceDate IS NOT NULL) AND (CO_Containers_1.DestinationDesc <> 'קונטרם') AND (CO_Containers_1.ReleaseForkliftDate IS NULL) AND (CO_Containers_1.ExitGAteDate IS NULL) AND 
                         (CO_Containers_1.Terminal = 'ILCXQ') AND (CP_Deal_1.HandlingTypeCode <> 'DP') AND (dbo.CO_ContainersReflect.Active <> 0) AND (dbo.CO_ContainersReflect.ReturnFromReflectDate IS NULL OR
                         dbo.CO_ContainersReflect.ReturnFromReflectDate = CONVERT(DATETIME, '1900-01-01 00:00:00', 102)) AND (dbo.CO_ContainersReflect.ExitToReflectDate IS NOT NULL)

GO
/* ===== FUNCTION: [dbo].[IntToHex] ===== */

CREATE function [dbo].[IntToHex] (@val int)
returns varchar(max)
begin
    declare @r varchar(max), @tmp int, @v1 int, @v2 int, @char varchar(1)
    set @tmp = @val
    set @r = ''
    while 1=1
    begin
        set @v1 = @tmp / 16
        set @v2 = @tmp % 16
        if @v2 = 0
            set @char = '0'
        else if @v2 = 1
            set @char = '1'
        else if @v2 = 2
            set @char = '2'
        else if @v2 = 3
            set @char = '3'
        else if @v2 = 4
            set @char = '4'
        else if @v2 = 5
            set @char = '5'
        else if @v2 = 6
            set @char = '6'
        else if @v2 = 7
            set @char = '7'
        else if @v2 = 8
            set @char = '8'
        else if @v2 = 9
            set @char = '9'
        else if @v2 = 10
            set @char = 'A'
        else if @v2 = 11
            set @char = 'B'
        else if @v2 = 12
            set @char = 'C'
        else if @v2 = 13
            set @char = 'D'
        else if @v2 = 14
            set @char = 'E'
        else if @v2 = 15
            set @char = 'F'
        set @tmp = @v1 
        set @r = @char + @r
        if @tmp = 0
            break
    end
      if len (@r) =1
      begin
         set @r='0' +  @r
      end


    return @r
end

GO
/* ===== FUNCTION: [dbo].[udf_GetNumeric] ===== */
CREATE FUNCTION dbo.udf_GetNumeric
(@strAlphaNumeric VARCHAR(256))
RETURNS VARCHAR(256)
AS
 BEGIN
 DECLARE @intAlpha INT
 SET @intAlpha = PATINDEX('%[^0-9]%', @strAlphaNumeric)
BEGIN
 WHILE @intAlpha > 0
BEGIN
 SET @strAlphaNumeric = STUFF(@strAlphaNumeric, @intAlpha, 1, '' )
SET @intAlpha = PATINDEX('%[^0-9]%', @strAlphaNumeric )
END
 END
 RETURN ISNULL(@strAlphaNumeric,0)
END

