/* ===== PROC: [dbo].[sp_ForkLiftActEmptyLoction] ===== */

CREATE  PROCEDURE [dbo].[sp_ForkLiftActEmptyLoction]
@container char(11),
@manifest char(6)
AS
SELECT     CO_Containers.Container AS מכולה, CO_ContainerProfile.ContainerLength AS גודל, CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      CO_Containers.NetoWeight AS משקל, CP_Deal.HandlingTypeCode AS קוד, CO_Containers.CarrierCode AS קו, CO_Containers.EntranceTruckID AS משאית, 
                      CO_Containers.LocationCode AS איתור, CO_Containers.WaitingTime AS המתנה, CO_ContainerProfile.ContainerNumber AS [מספר מכולה], 
                      CO_Containers.ContainerCapacity AS אפיון, CO_Containers.EntranceDriverID AS [ת.ז נהג], CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], 
                      TC_Client.ClientNameHe AS לקוח, CO_Containers.Manifest, TB_Drivers.DriverName AS נהג, CO_Containers.ExitDate, CO_Containers.DealNumber, 
                      CO_Containers.DealNumberSub, TB_WorkType.WorkTypeDesc AS עבודה, TB_WorkType.Comment, CO_Containers.UNCode1
FROM         CO_Containers INNER JOIN
                      CO_ContainerProfile ON CO_Containers.Container = CO_ContainerProfile.Container LEFT OUTER JOIN
                      TB_WorkType INNER JOIN
                      CP_Order ON TB_WorkType.WorkTypeCode = CP_Order.WorkTypeCode ON CO_Containers.Container = CP_Order.Container AND 
                      CO_Containers.Manifest = CP_Order.Manifest LEFT OUTER JOIN
                      TB_Drivers ON CO_Containers.EntranceDriverID = TB_Drivers.DriverID AND CO_Containers.ExitDriverID = TB_Drivers.DriverID LEFT OUTER JOIN
                      CP_Deal ON CO_Containers.DealNumber = CP_Deal.DealNumber LEFT OUTER JOIN
                      TC_Client ON CO_Containers.CarrierCode = TC_Client.ClientCode
WHERE     (CO_Containers.Container = @container) AND (CO_Containers.Manifest = @manifest) AND (CO_Containers.EntranceDate IS NOT NULL) AND 
                      (CO_Containers.ExitDate IS NULL) AND (CO_Containers.LocationCode IS NULL)


GO
/* ===== PROC: [dbo].[sp_ForkLiftActQueryMorethen1] ===== */


CREATE  PROCEDURE [dbo].[sp_ForkLiftActQueryMorethen1](@container char(11),
@manifest char(6))
AS 
SELECT     CO_Containers.Container AS מכולה, CO_ContainerProfile.ContainerLength AS גודל, CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      CO_Containers.NetoWeight AS משקל, CP_Deal.HandlingTypeCode AS קוד, CO_Containers.CarrierCode AS קו, '' AS משאית, 
                      CO_Containers.RecommendedLocationCode AS [איתור צפוי], CO_Containers.LocationCode AS איתור, CO_Containers.WaitingTime AS המתנה, 
                      CO_ContainerProfile.ContainerNumber AS [מספר מכולה], CO_Containers.ContainerCapacity AS אפיון, '' AS [ת.ז נהג], '' AS [חברת הובלה], 
                      TC_Client.ClientNameHe AS לקוח, CO_Containers.Manifest AS מיצהר, '' AS נהג, CO_Containers.DealNumber AS עיסקה, CO_Containers.ExitDate, 
                      CO_Containers.MarksNumbers, '' AS עבודה, CO_Containers.EntranceDate, CO_Containers.RegisterDate, CP_Deal.RecieveCommisionCode, 
                      CO_Containers.ReleaseForkliftDate, CO_Containers.DealNumberSub AS [סידורי בעיסקה], CO_Containers.UNCode1, 
                      TC_HazardousSubstances.ClassificationClassCode
FROM         CO_Containers INNER JOIN
                      CP_Deal ON CO_Containers.DealNumber = CP_Deal.DealNumber LEFT OUTER JOIN
                      TC_HazardousSubstances ON CO_Containers.UNCode1 = TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                      TC_Client ON CO_Containers.CarrierCode = TC_Client.ClientCode LEFT OUTER JOIN
                      CO_ContainerProfile ON CO_Containers.Container = CO_ContainerProfile.Container LEFT OUTER JOIN
                      TB_Drivers ON CO_Containers.EntranceDriverID = TB_Drivers.DriverID AND CO_Containers.ExitDriverID = TB_Drivers.DriverID
WHERE     (CO_Containers.Container = @container) AND (CO_Containers.EntranceDate IS NOT NULL) AND (CO_Containers.Manifest = @manifest) OR
                      (CO_Containers.Container = @container) AND (CO_Containers.Manifest = @manifest) AND (CO_Containers.RegisterDate IS NOT NULL)


