/* ===== PROC: [dbo].[sp_ForkLiftContainerNotinlistIn] ===== */



CREATE PROCEDURE [dbo].[sp_ForkLiftContainerNotinlistIn](@containernumber char(7), @Terminal char(5))
AS 
SELECT  TOP 1   CO_Containers.Container AS מכולה, CO_ContainerProfile.ContainerLength AS גודל, CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      CO_Containers.NetoWeight AS משקל, CP_Deal.HandlingTypeCode AS קוד, CO_Containers.CarrierCode AS קו, CO_Containers.EntranceTruckID AS משאית, 
                      CO_Containers.RecommendedLocationCode AS [איתור צפוי], CO_Containers.LocationCode AS איתור, CO_Containers.WaitingTime AS המתנה, 
                      CO_ContainerProfile.ContainerNumber AS [מספר מכולה], CO_Containers.ContainerCapacity AS אפיון, CO_Containers.EntranceDriverID AS [ת.ז נהג], 
                      CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], TC_Client.ClientNameHe AS לקוח, CO_Containers.Manifest, TB_Drivers.DriverName AS נהג, 
                      CO_Containers.DealNumber, CO_Containers.DealNumberSub, CO_Containers.ExitDate, CO_Containers.RegisterDate, CO_Containers.EntranceDate, 
                      CO_Containers.MarksNumbers, CO_Containers.UNCode1, TC_HazardousSubstances.ClassificationClassCode
FROM         CO_Containers INNER JOIN
                      CO_ContainerProfile ON CO_Containers.Container = CO_ContainerProfile.Container INNER JOIN
                      TC_Client ON CO_Containers.CarrierCode = TC_Client.ClientCode INNER JOIN
                      CP_Deal ON CO_Containers.DealNumber = CP_Deal.DealNumber LEFT OUTER JOIN
                      TC_HazardousSubstances ON CO_Containers.UNCode1 = TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                      TB_Drivers ON CO_Containers.EntranceDriverID = TB_Drivers.DriverID AND CO_Containers.ExitDriverID = TB_Drivers.DriverID
WHERE     (CO_Containers.ExitDate IS NULL) AND (CO_Containers.EntranceForkliftDate IS NULL) AND (CO_ContainerProfile.ContainerNumber = @containernumber) AND 
                      (NOT (CO_Containers.EntranceDate IS NULL)) OR
                      (CO_Containers.ExitDate IS NULL) AND (CO_Containers.EntranceForkliftDate IS NULL) AND (CO_ContainerProfile.ContainerNumber = @containernumber) AND 
                      (CO_Containers.RegisterDate IS NOT NULL)  AND (dbo.CO_Containers.Terminal = @Terminal)
GO
