                      CO_Containers.LocationCode AS איתור, CO_Containers.WaitingTime AS המתנה, CO_ContainerProfile.ContainerNumber AS [מספר מכולה], 
                      CO_Containers.ContainerCapacity AS אפיון, CO_Containers.EntranceDriverID AS [ת.ז נהג], CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], 
