/* ===== PROC: [dbo].[sp_ForkLiftContainersActEMOut] ===== */
CREATE PROCEDURE [dbo].[sp_ForkLiftContainersActEMOut](@CarrierCode varchar(11),
@TruckID varchar(8)  , @Terminal char(5)  )
AS 
if (SELECT  COUNT(*) AS Expr1
FROM         dbo.CP_TrucksConterm
WHERE     (Terminal = @Terminal) AND (CarrierCode = @CarrierCode) AND (TruckID = @TruckID) AND 
         (Container IS NOT NULL) AND (EntranceDate IS NOT NULL) AND 
     (ExitDate IS NULL))> 0
begin
if (SELECT  COUNT(*) AS Expr1
FROM         dbo.CP_TrucksConterm
WHERE     (Terminal = @Terminal) AND (CarrierCode = @CarrierCode) AND (TruckID = @TruckID) AND 
         (Container IS  NULL) AND (EntranceDate IS NOT NULL) AND 
     (ExitDate IS NULL))> 0
		   begin
					SELECT     TOP (100) PERCENT dbo.CP_TrucksConterm.Container AS מכולה, dbo.CP_TrucksConterm.ContainerLength AS גודל, dbo.CP_TrucksConterm.ContainerTypeCode AS סוג, 
										  'EM' AS קוד, dbo.CP_TrucksConterm.CarrierCode AS קו, dbo.CP_TrucksConterm.TruckID AS משאית, dbo.CO_Containers.LocationCode AS איתור, 
										  dbo.CP_TrucksConterm.WaittingTime AS המתנה, SUBSTRING(dbo.CP_TrucksConterm.Container, 5, 7) AS [מספר מכולה], 'EM' AS אפיון, 
										  dbo.CP_TrucksConterm.DriverID AS [ת.ז נהג], dbo.TB_Drivers.TruckCompanyCode AS [חברת הובלה], dbo.TC_Client.ClientNameHe AS לקוח, NULL AS Manifest, NULL 
										  AS DealNumber, NULL AS DealNumberSub, dbo.CP_TrucksConterm.EntranceDate, NULL AS ReleaseForkliftDate, NULL AS ExitGAteDate, NULL AS DestinationDesc, NULL 
										  AS ReflectOrderDate, NULL AS חומס, dbo.CP_TrucksConterm.AVDM, dbo.TB_Drivers.DriverName, cast(dbo.CO_Containers.NetoWeight as int) as NetoWeight, dbo.CO_Containers.MarksNumbers, 
										  '' AS [איתור צפוי], cast(dbo.CO_Containers.NetoWeight as int) AS משקל,
										  CO_Containers.RecommendedLocationRemarks AS [הערה לאיתור], '' AS [מצהר יצוא]
					FROM         dbo.CP_TrucksConterm INNER JOIN
										  dbo.TB_Drivers ON dbo.CP_TrucksConterm.DriverID = dbo.TB_Drivers.DriverID INNER JOIN
										  dbo.TC_Client ON dbo.CP_TrucksConterm.CarrierCode = dbo.TC_Client.ClientCode LEFT OUTER JOIN
										  dbo.CO_Containers ON dbo.CP_TrucksConterm.Container = dbo.CO_Containers.Container
					WHERE       (dbo.CP_TrucksConterm.Terminal =@Terminal) AND  (dbo.CP_TrucksConterm.EntranceDate IS NOT NULL) AND (dbo.CP_TrucksConterm.ExitDate IS NULL) AND 
										  (dbo.CP_TrucksConterm.EntryTarget1 = 'טעינת מכולה ריקה') 
										  AND (dbo.CP_TrucksConterm.CarrierCode = @CarrierCode) AND (dbo.CP_TrucksConterm.TruckID = @TruckID) AND (dbo.CO_Containers.ExitDate IS NULL)   AND  (dbo.CP_TrucksConterm.Container IS NULL) 
		  end
  else
   begin
			SELECT     TOP (100) PERCENT dbo.CP_TrucksConterm.Container AS מכולה, dbo.CP_TrucksConterm.ContainerLength AS גודל, dbo.CP_TrucksConterm.ContainerTypeCode AS סוג, 
								  'EM' AS קוד, dbo.CP_TrucksConterm.CarrierCode AS קו, dbo.CP_TrucksConterm.TruckID AS משאית, dbo.CO_Containers.LocationCode AS איתור, 
								  dbo.CP_TrucksConterm.WaittingTime AS המתנה, SUBSTRING(dbo.CP_TrucksConterm.Container, 5, 7) AS [מספר מכולה], 'EM' AS אפיון, 
								  dbo.CP_TrucksConterm.DriverID AS [ת.ז נהג], dbo.TB_Drivers.TruckCompanyCode AS [חברת הובלה], dbo.TC_Client.ClientNameHe AS לקוח, NULL AS Manifest, NULL 
								  AS DealNumber, NULL AS DealNumberSub, dbo.CP_TrucksConterm.EntranceDate, NULL AS ReleaseForkliftDate, NULL AS ExitGAteDate, NULL AS DestinationDesc, NULL 
								  AS ReflectOrderDate, NULL AS חומס, dbo.CP_TrucksConterm.AVDM, dbo.TB_Drivers.DriverName, cast(dbo.CO_Containers.NetoWeight as int) as NetoWeight, dbo.CO_Containers.MarksNumbers, 
								  '' AS [איתור צפוי], cast(dbo.CO_Containers.NetoWeight as int) AS משקל,
								  CO_Containers.RecommendedLocationRemarks AS [הערה לאיתור], '' AS [מצהר יצוא]
			FROM         dbo.CP_TrucksConterm INNER JOIN
								  dbo.TB_Drivers ON dbo.CP_TrucksConterm.DriverID = dbo.TB_Drivers.DriverID INNER JOIN
								  dbo.TC_Client ON dbo.CP_TrucksConterm.CarrierCode = dbo.TC_Client.ClientCode LEFT OUTER JOIN
								  dbo.CO_Containers ON dbo.CP_TrucksConterm.Container = dbo.CO_Containers.Container
			WHERE       (dbo.CP_TrucksConterm.Terminal =@Terminal) AND  (dbo.CP_TrucksConterm.EntranceDate IS NOT NULL) AND (dbo.CP_TrucksConterm.ExitDate IS NULL) AND 
								  (dbo.CP_TrucksConterm.EntryTarget1 = 'טעינת מכולה ריקה') 
								  AND (dbo.CP_TrucksConterm.CarrierCode = @CarrierCode) AND (dbo.CP_TrucksConterm.TruckID = @TruckID) AND (dbo.CO_Containers.ExitDate IS NULL)   AND  (dbo.CP_TrucksConterm.Container IS NOT NULL) 
  end
end
else
begin
SELECT        TOP (100) PERCENT CP_TrucksConterm.Container AS מכולה, CP_TrucksConterm.ContainerLength AS גודל, CP_TrucksConterm.ContainerTypeCode AS סוג, 'EM' AS קוד, CP_TrucksConterm.CarrierCode AS קו, 
                         CP_TrucksConterm.TruckID AS משאית, CP_TrucksConterm.LocationCode AS איתור, CP_TrucksConterm.WaittingTime AS המתנה, SUBSTRING(CP_TrucksConterm.Container, 5, 7) AS [מספר מכולה], 'EM' AS אפיון, 
                         CP_TrucksConterm.DriverID AS [ת.ז נהג], TB_Drivers.TruckCompanyCode AS [חברת הובלה], TC_Client.ClientNameHe AS לקוח, NULL AS Manifest, NULL AS DealNumber, NULL AS DealNumberSub, 
                         CP_TrucksConterm.EntranceDate, NULL AS ReleaseForkliftDate, NULL AS ExitGAteDate, NULL AS DestinationDesc, NULL AS ReflectOrderDate, NULL AS חומס, CP_TrucksConterm.AVDM, TB_Drivers.DriverName, 
                         0 AS NetoWeight, '' AS MarksNumbers, CASE WHEN TB_RecommendedLocation.RecommendedLocationCode IS NULL THEN '' ELSE TB_RecommendedLocation.RecommendedLocationCode END AS [איתור צפוי], 0 AS משקל, 
                         CO_Containers.RecommendedLocationRemarks AS [הערה לאיתור], '' AS [מצהר יצוא]
FROM            CP_TrucksConterm INNER JOIN
                         TB_Drivers ON CP_TrucksConterm.DriverID = TB_Drivers.DriverID INNER JOIN
                         TC_Client ON CP_TrucksConterm.CarrierCode = TC_Client.ClientCode LEFT OUTER JOIN
                         TB_RecommendedLocation ON CP_TrucksConterm.Terminal = TB_RecommendedLocation.Terminal AND CP_TrucksConterm.CarrierCode = TB_RecommendedLocation.CarrierCode AND 
                         CP_TrucksConterm.ContainerLength = TB_RecommendedLocation.ContainerLength AND CP_TrucksConterm.ContainerTypeCode = TB_RecommendedLocation.ContainerTypeCode LEFT OUTER JOIN
                         CO_Containers ON CP_TrucksConterm.Container = CO_Containers.Container
WHERE    (dbo.CP_TrucksConterm.Terminal =@Terminal) AND (dbo.CP_TrucksConterm.CarrierCode = @CarrierCode) AND (dbo.CP_TrucksConterm.TruckID = @TruckID) AND (dbo.CP_TrucksConterm.EntranceDate IS NOT NULL) AND
                       (dbo.CP_TrucksConterm.ExitDate IS NULL) AND (dbo.CP_TrucksConterm.EntryTarget1 = 'טעינת מכולה ריקה')
end

GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersActIn] ===== */





CREATE  PROCEDURE [dbo].[sp_ForkLiftContainersActIn](@container char(11),
@manifest char(6))
AS 
SELECT   TOP 1  CO_Containers.Container AS מכולה, CO_ContainerProfile.ContainerLength AS גודל, CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      CO_Containers.NetoWeight AS משקל, CP_Deal.HandlingTypeCode AS קוד, CO_Containers.CarrierCode AS קו, CO_Containers.EntranceTruckID AS משאית,
                       CO_Containers.RecommendedLocationCode AS [איתור צפוי], CO_Containers.LocationCode AS איתור, CO_Containers.WaitingTime AS המתנה, 
                      CO_ContainerProfile.ContainerNumber AS [מספר מכולה], CO_Containers.ContainerCapacity AS אפיון, CO_Containers.EntranceDriverID AS [ת.ז נהג], 
                      CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], TC_Client.ShortClientName AS לקוח, CO_Containers.Manifest, 
                      TB_Drivers.DriverName AS נהג, CO_Containers.DealNumber, TB_WorkType.WorkTypeDesc AS עבודה, CP_Order.Comment, 
                      CO_Containers.MarksNumbers, CO_Containers.EntranceForkliftDate, CO_Containers.ExitDate, CO_Containers.EntranceDate, 
                      CO_Containers.DealNumberSub, CO_Containers.UNCode1, TC_HazardousSubstances.ClassificationClassCode, dbo.CO_Containers.AVDM,CP_Deal.Permit,
                      CO_Containers.RecommendedLocationRemarks AS [הערה לאיתור], dbo.CO_ContainersEX.ManifestEX AS [מצהר יצוא]
FROM         TB_Drivers RIGHT OUTER JOIN
                      CO_Containers INNER JOIN
                      CO_ContainerProfile ON CO_Containers.Container = CO_ContainerProfile.Container LEFT OUTER JOIN
					  dbo.CO_ContainersEX ON dbo.CO_Containers.Container = dbo.CO_ContainersEX.Container LEFT OUTER JOIN
                      TC_HazardousSubstances ON CO_Containers.UNCode1 = TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                      TB_WorkType INNER JOIN
                      CP_Order ON TB_WorkType.WorkTypeCode = CP_Order.WorkTypeCode ON CO_Containers.Container = CP_Order.Container AND 
                      CO_Containers.Manifest = CP_Order.Manifest ON TB_Drivers.DriverID = CO_Containers.EntranceDriverID LEFT OUTER JOIN
                      CP_Deal INNER JOIN
                      TC_Client ON CP_Deal.RecieveCommisionCode = TC_Client.ClientCode ON CO_Containers.DealNumber = CP_Deal.DealNumber
WHERE     (CO_Containers.Container = @container) AND (CO_Containers.Manifest = @manifest) AND (CO_Containers.EntranceForkliftDate IS NULL) AND 
                      (CO_Containers.ExitDate IS NULL) AND (CO_Containers.EntranceDate IS NOT NULL) AND (CO_Containers.LocationCode IS NULL) OR
                      (CO_Containers.Container = @container) AND (CO_Containers.Manifest = @manifest) AND (CO_Containers.EntranceForkliftDate IS NULL) AND 
                      (CO_Containers.ExitDate IS NULL) AND (CO_Containers.EntranceDate IS NOT NULL) AND (LTRIM(CO_Containers.LocationCode) = '')




GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersActOut] ===== */




  



CREATE  PROCEDURE [dbo].[sp_ForkLiftContainersActOut](@container char(11),
@manifest char(6))
AS 
SELECT     TOP (1) dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      dbo.CO_Containers.NetoWeight AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, dbo.CO_Containers.CarrierCode AS קו, dbo.CO_Containers.ExitTruckID AS משאית, 
                      dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.WaitingTime AS המתנה, dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], 
                      dbo.CO_Containers.ContainerCapacity AS אפיון, dbo.CO_Containers.EntranceDriverID AS [ת.ז נהג], dbo.CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], 
                      dbo.TC_Client.ShortClientName AS לקוח, dbo.ReturnDriverName(dbo.CO_Containers.ExitDriverID) AS נהג, dbo.CO_Containers.Manifest, dbo.CO_Containers.ExitDate, 
                      dbo.CO_Containers.DealNumber, dbo.CO_Containers.DealNumberSub, dbo.CO_Containers.MarksNumbers, '' AS redate, 
                      dbo.CO_Containers.RecommendedLocationCode AS [איתור צפוי], dbo.CO_Containers.RegisterDate, dbo.CO_Containers.UNCode1, 
                      dbo.TC_HazardousSubstances.ClassificationClassCode, dbo.CO_Containers.AVDM, dbo.CP_Deal.Permit, CASE WHEN CO_Containers.ExitToReflectDate IS NULL 
                      THEN 0 ELSE 1 END AS reflect,
					  CO_Containers.RecommendedLocationRemarks AS [הערה לאיתור], dbo.CO_ContainersEX.ManifestEX AS [מצהר יצוא]
FROM         dbo.TC_HazardousSubstances RIGHT OUTER JOIN
                      dbo.CO_Containers INNER JOIN
                      dbo.CP_GatePassAccompany ON dbo.CO_Containers.Manifest = dbo.CP_GatePassAccompany.Manifest AND 
                      dbo.CO_Containers.Container = dbo.CP_GatePassAccompany.Container INNER JOIN
                      dbo.CP_GatePass ON dbo.CP_GatePassAccompany.DeliveryOrderNumber = dbo.CP_GatePass.DeliveryOrderNumber ON 
                      dbo.TC_HazardousSubstances.UNCode = dbo.CO_Containers.UNCode1 LEFT OUTER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container LEFT OUTER JOIN
					  dbo.CO_ContainersEX ON dbo.CO_Containers.Container = dbo.CO_ContainersEX.Container LEFT OUTER JOIN
                      dbo.TC_Client INNER JOIN
                      dbo.CP_Deal ON dbo.TC_Client.ClientCode = dbo.CP_Deal.RecieveCommisionCode ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber
WHERE     (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.Container = @container) AND (dbo.CO_Containers.Manifest = @manifest) AND 
                      (dbo.CO_Containers.ReleaseForkliftDate IS NULL) AND (dbo.CP_GatePassAccompany.DeliveryOrderNumber IS NOT NULL) AND 
                      (dbo.CP_GatePass.DeliveryOrderDate >= CONVERT(DATETIME, '2011-02-01 00:00:00', 102))






GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersActQuery] ===== */


CREATE PROCEDURE [dbo].[sp_ForkLiftContainersActQuery]
(@containernumber char(7),@Terminal char(5))
AS 
SELECT     TOP (1) dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      dbo.CO_Containers.NetoWeight AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, dbo.CO_Containers.CarrierCode AS קו, '' AS משאית, 
                      dbo.CO_Containers.RecommendedLocationCode AS [איתור צפוי], dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.WaitingTime AS המתנה, 
                      dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], dbo.CO_Containers.ContainerCapacity AS אפיון, '' AS [ת.ז נהג], '' AS [חברת הובלה], 
                      dbo.TC_Client.ShortClientName AS לקוח, dbo.CO_Containers.Manifest AS מיצהר, CASE WHEN CO_Containers.ReserveDate IS NULL 
                      THEN '' ELSE 'מכולה שמורה' END AS נהג, dbo.CO_Containers.DealNumber, dbo.CO_Containers.ExitDate, dbo.CO_Containers.MarksNumbers, 
     
                 CASE WHEN cp_order.WorkTypeCode = '04' AND NOT (dbo.CO_Containers.ReturnFromReflectDate IS NULL OR
                      dbo.CO_Containers.ReturnFromReflectDate = '01/01/1900 00:00:00') THEN '' ELSE dbo.TB_WorkType.WorkTypeDesc + ' ' + CONVERT(VARCHAR(10), 
                      dbo.CP_Order.TargetDate, 103) END + ' ' + CASE WHEN cp_order.ExaminTestType IS NULL THEN '' ELSE cp_order.ExaminTestType END AS עבודה, 
                      dbo.CO_Containers.EntranceDate, dbo.CO_Containers.RegisterDate, dbo.CP_Deal.RecieveCommisionCode, dbo.CO_Containers.ReleaseForkliftDate, 
                      dbo.CO_Containers.DealNumberSub, dbo.CO_Containers.UNCode1, dbo.TC_HazardousSubstances.ClassificationClassCode, dbo.CO_Containers.AVDM, 
                      dbo.CP_Deal.Permit, dbo.CO_Containers.RecommendedLocationRemarks AS [הערה לאיתור], dbo.CO_ContainersEX.ManifestEX AS [מצהר יצוא]
FROM            dbo.CO_Containers INNER JOIN
				dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container LEFT OUTER JOIN
				dbo.CO_ContainersEX ON dbo.CO_Containers.Container = dbo.CO_ContainersEX.Container LEFT OUTER JOIN
				dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode LEFT OUTER JOIN
				dbo.TB_WorkType INNER JOIN
				dbo.CP_Order ON dbo.TB_WorkType.WorkTypeCode = dbo.CP_Order.WorkTypeCode ON dbo.CO_Containers.Container = dbo.CP_Order.Container AND dbo.CO_Containers.Manifest = dbo.CP_Order.Manifest LEFT OUTER JOIN
				dbo.CP_Deal INNER JOIN
				dbo.TC_Client ON dbo.CP_Deal.RecieveCommisionCode = dbo.TC_Client.ClientCode ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber
WHERE     (dbo.CO_ContainerProfile.ContainerNumber LIKE @containernumber) AND (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitDate IS NULL) 
                      AND (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND (dbo.CO_Containers.Terminal = @Terminal) OR
                      (dbo.CO_ContainerProfile.ContainerNumber LIKE @containernumber) AND (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CP_Deal.HandlingTypeCode <> 'EM') AND 
                      (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND  (dbo.CP_Deal.HandlingTypeCode <> 'CL') AND (dbo.CO_Containers.RegisterDate IS NOT NULL) AND (dbo.CO_Containers.Terminal = @Terminal)
ORDER BY dbo.CO_Containers.EntranceDate DESC



GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersActQuery_APP] ===== */

-- EXEC [dbo].[sp_ForkLiftContainersActQuery_APP] @containernumber = N'1%', @Terminal = N'ILCXQ'
CREATE PROCEDURE [dbo].[sp_ForkLiftContainersActQuery_APP]
(@ContainerNumber nvarchar(7),@Terminal char(5))
AS 

SELECT     TOP (5)  dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      dbo.CO_Containers.NetoWeight AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, dbo.CO_Containers.CarrierCode AS קו, '' AS משאית, 
                      dbo.CO_Containers.RecommendedLocationCode AS [איתור צפוי], dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.WaitingTime AS המתנה, 
                      dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], dbo.CO_Containers.ContainerCapacity AS אפיון, '' AS [ת.ז נהג], '' AS [חברת הובלה], 
                      dbo.TC_Client.ShortClientName AS לקוח, dbo.CO_Containers.Manifest AS מיצהר, CASE WHEN CO_Containers.ReserveDate IS NULL 
                      THEN '' ELSE 'מכולה שמורה' END AS נהג, dbo.CO_Containers.DealNumber, dbo.CO_Containers.ExitDate, dbo.CO_Containers.MarksNumbers, 
     
                 CASE WHEN CP_Order.WorkTypeCode = '04' AND NOT (dbo.CO_Containers.ReturnFromReflectDate IS NULL OR
                      dbo.CO_Containers.ReturnFromReflectDate = '01/01/1900 00:00:00') THEN '' ELSE dbo.TB_WorkType.WorkTypeDesc + ' ' + CONVERT(VARCHAR(10), 
                      dbo.CP_Order.TargetDate, 103) END + ' ' + CASE WHEN cp_order.ExaminTestType IS NULL THEN '' ELSE cp_order.ExaminTestType END AS עבודה, 
                      dbo.CO_Containers.EntranceDate, dbo.CO_Containers.RegisterDate, dbo.CP_Deal.RecieveCommisionCode, dbo.CO_Containers.ReleaseForkliftDate, 
                      dbo.CO_Containers.DealNumberSub, dbo.CO_Containers.UNCode1, dbo.TC_HazardousSubstances.ClassificationClassCode, dbo.CO_Containers.AVDM, 
                      dbo.CP_Deal.Permit, dbo.CO_Containers.RecommendedLocationRemarks AS [הערה לאיתור], dbo.CO_ContainersEX.ManifestEX AS [מצהר יצוא]
FROM            dbo.CO_Containers INNER JOIN
				dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container LEFT OUTER JOIN
				dbo.CO_ContainersEX ON  CO_Containers.Manifest = CO_ContainersEX.Manifest and dbo.CO_Containers.Container = dbo.CO_ContainersEX.Container LEFT OUTER JOIN
				dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode LEFT OUTER JOIN
				dbo.TB_WorkType INNER JOIN
				dbo.CP_Order ON dbo.TB_WorkType.WorkTypeCode = dbo.CP_Order.WorkTypeCode ON dbo.CO_Containers.Container = dbo.CP_Order.Container AND dbo.CO_Containers.Manifest = dbo.CP_Order.Manifest LEFT OUTER JOIN
				dbo.CP_Deal INNER JOIN
				dbo.TC_Client ON dbo.CP_Deal.RecieveCommisionCode = dbo.TC_Client.ClientCode ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber
WHERE     (dbo.CO_Containers.ContainerNumber LIKE @ContainerNumber) 
      AND (dbo.CO_Containers.EntranceDate IS NOT NULL) 
      AND (dbo.CO_Containers.ExitDate IS NULL) 
      AND (dbo.CP_Deal.HandlingTypeCode NOT IN('DP','MG')) 
	  AND (dbo.CO_Containers.Terminal = @Terminal) 
ORDER BY dbo.CO_Containers.EntranceDate DESC

GO
