                      dbo.CO_Containers.ReturnFromReflectDate = '01/01/1900 00:00:00') THEN '' ELSE dbo.TB_WorkType.WorkTypeDesc + ' ' + CONVERT(VARCHAR(10), 
                      dbo.CP_Order.TargetDate, 103) END + ' ' + CASE WHEN cp_order.ExaminTestType IS NULL THEN '' ELSE cp_order.ExaminTestType END AS עבודה, 
                      dbo.CO_Containers.EntranceDate, dbo.CO_Containers.RegisterDate, dbo.CP_Deal.RecieveCommisionCode, dbo.CO_Containers.ReleaseForkliftDate, 
                      dbo.CO_Containers.DealNumberSub, dbo.CO_Containers.UNCode1, dbo.TC_HazardousSubstances.ClassificationClassCode, dbo.CO_Containers.AVDM, 
                      dbo.CP_Deal.Permit, dbo.CO_Containers.RecommendedLocationRemarks AS [הערה לאיתור]
FROM         dbo.CO_Containers INNER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container LEFT OUTER JOIN
                      dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                      dbo.TB_WorkType INNER JOIN
                      dbo.CP_Order ON dbo.TB_WorkType.WorkTypeCode = dbo.CP_Order.WorkTypeCode ON dbo.CO_Containers.Container = dbo.CP_Order.Container AND 
                      dbo.CO_Containers.Manifest = dbo.CP_Order.Manifest LEFT OUTER JOIN
                      dbo.CP_Deal INNER JOIN
                      dbo.TC_Client ON dbo.CP_Deal.RecieveCommisionCode = dbo.TC_Client.ClientCode ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber
WHERE     (dbo.CO_ContainerProfile.ContainerNumber LIKE @containernumber) AND (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitDate IS NULL) 
                      AND (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND (dbo.CO_Containers.Terminal = @Terminal) OR
                      (dbo.CO_ContainerProfile.ContainerNumber LIKE @containernumber) AND (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CP_Deal.HandlingTypeCode <> 'EM') AND 
                      (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND  (dbo.CP_Deal.HandlingTypeCode <> 'CL') AND (dbo.CO_Containers.RegisterDate IS NOT NULL) AND (dbo.CO_Containers.Terminal = @Terminal)
ORDER BY dbo.CO_Containers.EntranceDate DESC */
GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersCheckEMOut] ===== */


CREATE PROCEDURE [dbo].[sp_ForkLiftContainersCheckEMOut]
   @ContainerNumber char(7),@CarrierCode char(9) , @ContainerTypeCode char(2), @ContainerLength char(2) , @Terminal char(5)
AS
BEGIN

/*SELECT     COUNT(*) AS Counter
FROM         dbo.CO_ContainerProfile INNER JOIN
dbo.CO_Containers ON dbo.CO_ContainerProfile.Container = dbo.CO_Containers.Container
WHERE    (dbo.CO_Containers.Terminal = @Terminal)  AND 
  (dbo.CO_Containers.CarrierCode = @CarrierCode) AND
 (dbo.CO_ContainerProfile.ContainerTypeCode =@ContainerTypeCode) AND 
(dbo.CO_ContainerProfile.ContainerLength =  @ContainerLength) AND 
(dbo.CO_ContainerProfile.ContainerNumber =@ContainerNumber) */

-- 07/05/2020 GILAT  שינוי בדיקת מכולת בוקינג למסירה - תוספת בדיקה שהמכולה ריקה והיא בקונטרם

SELECT      COUNT(*) AS Counter
FROM        dbo.CO_ContainerProfile 
INNER JOIN  dbo.CO_Containers ON dbo.CO_ContainerProfile.Container = dbo.CO_Containers.Container 
INNER JOIN  dbo.CP_Deal ON dbo.CO_Containers.Manifest = dbo.CP_Deal.Manifest AND dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber
WHERE     (dbo.CO_Containers.Terminal = @Terminal) 
AND (dbo.CO_Containers.CarrierCode = @CarrierCode) 
AND (dbo.CO_ContainerProfile.ContainerTypeCode = @ContainerTypeCode) 
AND (dbo.CO_ContainerProfile.ContainerLength = @ContainerLength) 
AND (dbo.CO_ContainerProfile.ContainerNumber = @ContainerNumber) 
AND (dbo.CP_Deal.HandlingTypeCode = 'EM') 
AND (dbo.CO_Containers.ExitDate IS NULL)



END





