/* ===== PROC: [dbo].[sp_ForkLiftContainersEM] ===== */


CREATE PROCEDURE [dbo].[sp_ForkLiftContainersEM]
@Terminal char(5)

AS


 SELECT     TOP (100) PERCENT dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.EntranceDate AS [תאריך כניסה], dbo.CO_Containers.CarrierCode AS קו, 
                      dbo.TC_Client.ClientName AS לקוח, dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], dbo.CO_Containers.Manifest, dbo.CO_Containers.DealNumber, 
                      dbo.CO_Containers.DealNumberSub, dbo.CP_Deal.HandlingTypeCode, dbo.CO_Containers.ShipAgentCode, dbo.CO_Containers.ExitDate
FROM         dbo.CO_Containers INNER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container LEFT OUTER JOIN
                      dbo.TC_Client ON dbo.CO_Containers.ShipAgentCode = dbo.TC_Client.ClientCode LEFT OUTER JOIN
                      dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber
WHERE  dbo.CO_Containers.Terminal=@Terminal AND    (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CP_Deal.HandlingTypeCode = 'EM') AND 
                      (dbo.CO_Containers.EntranceDate >= CONVERT(DATETIME, '2010-10-01 00:00:00', 102)) AND (dbo.CO_Containers.ReserveDate IS NULL)
ORDER BY [תאריך כניסה]



GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersEMOut] ===== */

CREATE PROCEDURE [dbo].[sp_ForkLiftContainersEMOut]

@Terminal char(5)

AS 
SELECT     TOP (100) PERCENT dbo.CP_TrucksConterm.Container AS מכולה, dbo.CP_TrucksConterm.ContainerLength AS גודל, 
                      dbo.CP_TrucksConterm.ContainerTypeCode AS סוג, 0 AS משקל, dbo.CP_TrucksConterm.CarrierCode AS קו, dbo.CP_TrucksConterm.TruckID AS משאית, 'EM' AS קוד, 
					dbo.CP_TrucksConterm.WaittingTime AS זמן, dbo.CP_TrucksConterm.AVDM AS AVDM,
                      0 AS איתור, dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], 'EM' AS אפיון, dbo.CP_TrucksConterm.DriverID AS [ת.ז נהג], 0 AS [חברת הובלה], 0 AS Expr1, 
                      0 AS Expr2, 0 AS Expr3, dbo.CP_TrucksConterm.EntranceDate, dbo.CP_TrucksConterm.ReleaseForkliftDate, 0 AS Expr4, NULL AS Expr5, 
                      dbo.CP_TrucksConterm.DestinationDesc, dbo.CP_TrucksConterm.AVDM as AVDM2, dbo.CP_TrucksConterm.EntryTarget1, 
                      dbo.CP_TrucksConterm.ExitDate
FROM         dbo.CP_TrucksConterm INNER JOIN
                      dbo.TB_Trucks ON dbo.CP_TrucksConterm.TruckID = dbo.TB_Trucks.TruckID LEFT OUTER JOIN
                      dbo.CO_ContainerProfile ON dbo.CP_TrucksConterm.Container = dbo.CO_ContainerProfile.Container
WHERE     (dbo.CP_TrucksConterm.EntranceDate IS NOT NULL)  AND 
                      (dbo.CP_TrucksConterm.EntryTarget1 = 'טעינת מכולה ריקה') 
					  AND (dbo.CP_TrucksConterm.ExitDate IS NULL) 
	--				  and ReleaseForkliftDate is null
					  AND (dbo.CP_TrucksConterm.Terminal = @Terminal)





GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersEMOutUpDate] ===== */




CREATE  PROCEDURE  [dbo].[sp_ForkLiftContainersEMOutUpDate]
	@container char(11),
	@exitforkliftoperatorID char(10),
	@exitforkliftID char(7),
	@releaseforkliftDate datetime,
	@TruckID varchar(8),
	@CarrierCode char(9)

AS
DECLARE @RecordID bigint


UPDATE    CO_Containers
SET       ExitForkliftOperatorID = @exitforkliftoperatorID, 
          ExitForkliftNumber = @exitforkliftID, 
		  ReleaseForkliftDate = GETDATE()
WHERE     Container = @container  
AND		  EntranceDate IS NOT NULL 
AND		  ExitDate IS NULL


IF (SELECT   COUNT(*) 
    FROM dbo.CP_TrucksConterm
	WHERE   CarrierCode = @CarrierCode    
    AND  TruckID =  @TruckID     
    AND  ExitDate IS NULL    
    AND  Container IS NULL    
    AND  ContainerLength = (SELECT  ContainerLength FROM dbo.CO_ContainerProfile WHERE Container = @container)   
	) > 1

	BEGIN 
			SELECT @RecordID = (SELECT  top 1  RecordID   FROM dbo.CP_TrucksConterm WHERE   CarrierCode = @CarrierCode AND    TruckID = @TruckID  AND 
			ExitDate IS NULL   AND 
			Container IS NULL   AND 
			ContainerLength = (SELECT  ContainerLength FROM dbo.CO_ContainerProfile WHERE Container = @container))
			
			UPDATE   dbo.CP_TrucksConterm SET     Container = @Container , UpCon20Two ='TRUE', releaseforkliftDate = getdate() where  RecordID = @RecordID

	END
ELSE
	BEGIN

			SELECT @RecordID = (SELECT  top 1  RecordID   FROM dbo.CP_TrucksConterm 
			                    WHERE  UpCon20Two = 0 
								AND CarrierCode = @CarrierCode 
								AND  TruckID = @TruckID  
								AND  ExitDate IS NULL   
								AND  ContainerLength = (SELECT  ContainerLength 
								                        FROM dbo.CO_ContainerProfile 
														WHERE Container = @container)   
														ORDER BY RecordID DESC)
			
			UPDATE   dbo.CP_TrucksConterm 
			SET     Container = @Container , releaseforkliftDate = getdate()
			WHERE  RecordID = @RecordID


	END










GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersEMOutUpDate_new] ===== */




