--SELECT  top 1  RecordID   FROM dbo.CP_TrucksConterm WHERE   CarrierCode = 'ZIM' AND    TruckID = '31099601'  AND 	ExitDate IS NULL   AND 	Container IS NULL AND ContainerLength = (SELECT  ContainerLength FROM dbo.CO_ContainerProfile WHERE Container = 'ZCSU8687402')


