/* ===== PROC: [dbo].[sp_ForkLiftContainersIn] ===== */




CREATE PROCEDURE [dbo].[sp_ForkLiftContainersIn]

@Terminal char(5)



AS 
SELECT     TOP (50) dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      dbo.CO_Containers.NetoWeight AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, RTRIM(dbo.CO_Containers.CarrierCode) AS קו, 
                      CASE WHEN TB_Trucks.EquipmentNumber IS NULL THEN EntranceTruckID ELSE TB_Trucks.EquipmentNumber END AS משאית, 
                      dbo.CO_Containers.RecommendedLocationCode AS איתור, dbo.CO_Containers.WaittingTime AS המתנה, dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], 
                      dbo.CO_Containers.ContainerCapacity AS אפיון, dbo.CO_Containers.EntranceDriverID AS [ת.ז נהג], dbo.CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], 
                      TC_Client_1.ClientName AS לקוח, dbo.CO_Containers.Manifest, dbo.TC_Client.ShortClientName AS RecieveCommision, dbo.CO_Containers.DealNumber, 
                      dbo.CO_Containers.DealNumberSub, dbo.CO_Containers.EntranceDate, dbo.CP_Deal.ImporterId, dbo.CO_Containers.ExitDate, dbo.CO_Containers.MarksNumbers, 
                      LTRIM(RTRIM(dbo.CO_Containers.LocationCode)) AS Expr1, dbo.TC_HazardousSubstances.ClassificationClass AS UN, dbo.CO_Containers.AVDM, TB_Trucks.EquipmentNumber,  dbo.CO_Containers.SubContractorIN
FROM         dbo.CP_Deal INNER JOIN
                      dbo.CO_Containers INNER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container ON 
                      dbo.CP_Deal.DealNumber = dbo.CO_Containers.DealNumber INNER JOIN
                      dbo.TC_Client ON dbo.CP_Deal.RecieveCommisionCode = dbo.TC_Client.ClientCode LEFT OUTER JOIN
                      dbo.TB_Trucks ON dbo.CO_Containers.EntranceTruckID = dbo.TB_Trucks.TruckID LEFT OUTER JOIN
                      dbo.TC_Client AS TC_Client_1 ON dbo.CP_Deal.ImporterId = TC_Client_1.ClientCode LEFT OUTER JOIN
                      dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode
WHERE                     (dbo.CO_Containers.ExitDate IS NULL) 
                      AND (dbo.CO_Containers.EntranceForkliftDate IS NULL) 
                      AND (dbo.CO_Containers.EntranceDate >= CONVERT(DATETIME, '2018-01-31 00:00:00', 102)) 
					  AND (dbo.CO_Containers.LocationCode IS NULL OR dbo.CO_Containers.LocationCode = '') 
					  AND (dbo.CO_Containers.EntranceTruckFirst <> '0' OR dbo.CO_Containers.EntranceTruckFirst IS NULL) 
					  AND (dbo.CO_Containers.ExitToMarlogDate IS NULL OR dbo.CO_Containers.ExitToMarlogDate = CONVERT(DATETIME, '1900-01-01 00:00:00', 102)) 
					  AND (dbo.CO_Containers.ReturnFromMarlogDate IS NULL OR dbo.CO_Containers.ReturnFromMarlogDate = CONVERT(DATETIME, '1900-01-01 00:00:00', 102)) 
					  AND (dbo.CO_Containers.ReserveDate IS NULL) 
					  AND (dbo.CO_Containers.Terminal = @Terminal) 
					  AND CP_Deal.HandlingTypeCode <> 'RC'
					  OR
                      (dbo.CO_Containers.ExitDate IS NULL) 
					  AND (dbo.CO_Containers.EntranceForkliftDate IS NULL) 
					  AND (dbo.CO_Containers.EntranceDate >= CONVERT(DATETIME, '2018-01-31 00:00:00', 102)) 
					  AND (dbo.CO_Containers.LocationCode IS NULL OR dbo.CO_Containers.LocationCode = '') 
					  AND (dbo.CO_Containers.EntranceTruckFirst <> '0' OR dbo.CO_Containers.EntranceTruckFirst IS NULL) 
					  AND (dbo.CO_Containers.ExitToMarlogDate IS NOT NULL) 
					  AND (dbo.CO_Containers.ReturnFromMarlogDate IS NOT NULL) 
					  AND (dbo.CO_Containers.ReserveDate IS NULL) 
					  AND (dbo.CO_Containers.Terminal = @Terminal)
					  AND CP_Deal.HandlingTypeCode <> 'RC'
/*
UNION
-->  תוספת עבור מכולות שחזרו משיקוף
SELECT        dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, dbo.CO_Containers.NetoWeight AS משקל, 
                         dbo.CP_Deal.HandlingTypeCode AS קוד, RTRIM(dbo.CO_Containers.CarrierCode) AS קו, CASE WHEN TB_Trucks.EquipmentNumber IS NULL THEN EntranceTruckID ELSE TB_Trucks.EquipmentNumber END AS משאית, 
                         dbo.CO_Containers.RecommendedLocationCode AS איתור, dbo.CO_Containers.WaittingTime AS המתנה, dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], dbo.CO_Containers.ContainerCapacity AS אפיון, 
                         dbo.CO_Containers.EntranceDriverID AS [ת.ז נהג], dbo.CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], TC_Client_1.ClientName AS לקוח, dbo.CO_Containers.Manifest, 
                         dbo.TC_Client.ShortClientName AS RecieveCommision, dbo.CO_Containers.DealNumber, dbo.CO_Containers.DealNumberSub, dbo.CO_Containers.EntranceDate, dbo.CP_Deal.ImporterId, dbo.CO_Containers.ExitDate, 
                         dbo.CO_Containers.MarksNumbers, LTRIM(RTRIM(dbo.CO_Containers.LocationCode)) AS Expr1, dbo.TC_HazardousSubstances.ClassificationClass AS UN, dbo.CO_Containers.AVDM
FROM            dbo.CP_Deal INNER JOIN
                         dbo.CO_Containers INNER JOIN
                         dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container ON dbo.CP_Deal.DealNumber = dbo.CO_Containers.DealNumber INNER JOIN
                         dbo.TC_Client ON dbo.CP_Deal.RecieveCommisionCode = dbo.TC_Client.ClientCode INNER JOIN
                         dbo.CO_ContainersReflect ON dbo.CO_Containers.Container = dbo.CO_ContainersReflect.Container AND dbo.CO_Containers.Manifest = dbo.CO_ContainersReflect.Manifest LEFT OUTER JOIN
                         dbo.TB_Trucks ON dbo.CO_Containers.EntranceTruckID = dbo.TB_Trucks.TruckID LEFT OUTER JOIN
                         dbo.TC_Client AS TC_Client_1 ON dbo.CP_Deal.ImporterId = TC_Client_1.ClientCode LEFT OUTER JOIN
                         dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode
WHERE                   (dbo.CO_Containers.ExitDate IS NULL) 
                    AND (dbo.CO_Containers.EntranceDate >= CONVERT(DATETIME, '2018-01-31 00:00:00', 102)) 
					AND (TRIM(dbo.CO_Containers.LocationCode) = 'משאית' or (TRIM(dbo.CO_Containers.LocationCode) = ''))  
					AND (dbo.CO_Containers.Terminal = @Terminal) 
					AND (dbo.CP_Deal.HandlingTypeCode <> 'RC') 
					AND (dbo.CO_ContainersReflect.Active <> 0) 
					AND (dbo.CO_ContainersReflect.ExitToReflectDate IS NOT NULL)  
                    AND (dbo.CO_ContainersReflect.ReturnFromReflectDate IS NOT NULL)
*/
ORDER BY המתנה DESC





GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersIn_App] ===== */




create PROCEDURE [dbo].[sp_ForkLiftContainersIn_App]

@Terminal char(5),
@Em nvarchar(10)

AS 
SELECT     TOP (50) dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      dbo.CO_Containers.NetoWeight AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, RTRIM(dbo.CO_Containers.CarrierCode) AS קו, 
                      CASE WHEN TB_Trucks.EquipmentNumber IS NULL THEN EntranceTruckID ELSE TB_Trucks.EquipmentNumber END AS משאית, 
                      dbo.CO_Containers.RecommendedLocationCode AS איתור, dbo.CO_Containers.WaittingTime AS המתנה, dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], 
                      dbo.CO_Containers.ContainerCapacity AS אפיון, dbo.CO_Containers.EntranceDriverID AS [ת.ז נהג], dbo.CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], 
                      TC_Client_1.ClientName AS לקוח, dbo.CO_Containers.Manifest, dbo.TC_Client.ShortClientName AS RecieveCommision, dbo.CO_Containers.DealNumber, 
                      dbo.CO_Containers.DealNumberSub, dbo.CO_Containers.EntranceDate, dbo.CP_Deal.ImporterId, dbo.CO_Containers.ExitDate, dbo.CO_Containers.MarksNumbers, 
                      LTRIM(RTRIM(dbo.CO_Containers.LocationCode)) AS Expr1, dbo.TC_HazardousSubstances.ClassificationClass AS UN, dbo.CO_Containers.AVDM
FROM         dbo.CP_Deal INNER JOIN
                      dbo.CO_Containers INNER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container ON 
                      dbo.CP_Deal.DealNumber = dbo.CO_Containers.DealNumber INNER JOIN
                      dbo.TC_Client ON dbo.CP_Deal.RecieveCommisionCode = dbo.TC_Client.ClientCode LEFT OUTER JOIN
                      dbo.TB_Trucks ON dbo.CO_Containers.EntranceTruckID = dbo.TB_Trucks.TruckID LEFT OUTER JOIN
                      dbo.TC_Client AS TC_Client_1 ON dbo.CP_Deal.ImporterId = TC_Client_1.ClientCode LEFT OUTER JOIN
                      dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode
WHERE   ((dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CO_Containers.EntranceForkliftDate IS NULL) AND (dbo.CO_Containers.EntranceDate >= CONVERT(DATETIME, 
                      '2018-01-31 00:00:00', 102)) AND (dbo.CO_Containers.LocationCode IS NULL OR
                      dbo.CO_Containers.LocationCode = '') AND (dbo.CO_Containers.EntranceTruckFirst <> '0' OR
                      dbo.CO_Containers.EntranceTruckFirst IS NULL) AND (dbo.CO_Containers.ExitToMarlogDate IS NULL OR
                      dbo.CO_Containers.ExitToMarlogDate = CONVERT(DATETIME, '1900-01-01 00:00:00', 102)) AND (dbo.CO_Containers.ReturnFromMarlogDate IS NULL OR
                      dbo.CO_Containers.ReturnFromMarlogDate = CONVERT(DATETIME, '1900-01-01 00:00:00', 102)) AND (dbo.CO_Containers.ReserveDate IS NULL) AND (dbo.CO_Containers.Terminal = @Terminal) 
					  AND CP_Deal.HandlingTypeCode <> 'RC'
					  OR
                      (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CO_Containers.EntranceForkliftDate IS NULL) AND (dbo.CO_Containers.EntranceDate >= CONVERT(DATETIME, 
                      '2018-01-31 00:00:00', 102)) AND (dbo.CO_Containers.LocationCode IS NULL OR
                      dbo.CO_Containers.LocationCode = '') AND (dbo.CO_Containers.EntranceTruckFirst <> '0' OR
                      dbo.CO_Containers.EntranceTruckFirst IS NULL) AND (dbo.CO_Containers.ExitToMarlogDate IS NOT NULL) AND 
                      (dbo.CO_Containers.ReturnFromMarlogDate IS NOT NULL) AND (dbo.CO_Containers.ReserveDate IS NULL) AND (dbo.CO_Containers.Terminal = @Terminal)
					  AND CP_Deal.HandlingTypeCode <> 'RC')
					  and (@Em <> 'Empty' or CP_Deal.HandlingTypeCode = 'EM')
ORDER BY המתנה DESC





GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersInUpDate] ===== */


CREATE PROCEDURE [dbo].[sp_ForkLiftContainersInUpDate]
@container char(11),
@manifest char(6) ,
@location  char(10),
@forkliftDatein datetime,
@ForkliftOperatorID char(10),
@entranceforkliftID char(7)
--@Terminal char(5)

AS

if (SELECT     COUNT(*) AS locationID
    FROM         dbo.TB_LocationTerminal
    WHERE      LocationCode = @location) = 0
BEGIN
	INSERT TB_LocationTerminal( LocationCode)  select @location
END

UPDATE  CO_Containers
SET LocationCode = @location, 
EntranceForkliftDate = getdate(), 
EntranceForkliftOperatorID = @ForkliftOperatorID, 
EntranceForkliftNumber = @entranceforkliftID
WHERE  (Container = @container) AND (Manifest = @manifest) --AND (Terminal = @Terminal)

UPDATE CP_Order set LocationCode = @location WHERE  (Container = @container) AND (Manifest = @manifest)

UPDATE TB_Location  set  Container = @container where   LocationCode  = @location and (LocationType like '%Container%' or LocationType like '%RTG%')



GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersInUpDateNEW] ===== */


CREATE PROCEDURE [dbo].[sp_ForkLiftContainersInUpDateNEW]
@container char(11),
@manifest char(6) ,
@location  char(10),
@forkliftDatein datetime,
@ForkliftOperatorID char(10),
@entranceforkliftID char(7),
@Terminal char(5)

AS

IF (SELECT     COUNT(*) AS locationID
    FROM         dbo.TB_LocationTerminal
    WHERE      LocationCode = @location) = 0
BEGIN
	INSERT TB_LocationTerminal( LocationCode)  select @location
END

UPDATE  CO_Containers
SET LocationCode = @location, 
EntranceForkliftDate = getdate(), 
EntranceForkliftOperatorID = @ForkliftOperatorID, 
EntranceForkliftNumber = @entranceforkliftID
WHERE  (Container = @container) AND (Manifest = @manifest) AND (Terminal = @Terminal)



UPDATE TB_Location 
SET  Container = @container 
WHERE (LocationCode  = @location)
AND (Terminal = @Terminal)
and (LocationType like '%Container%' or LocationType like '%RTG%')



GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersLoctionUpDate] ===== */


CREATE PROCEDURE [dbo].[sp_ForkLiftContainersLoctionUpDate]
@container char(11),
@manifest char(6) ,
@location  char(10)  


as

declare @locationBefore  char(10) 



select @locationBefore = (SELECT     CASE WHEN LocationCode IS NULL THEN '' ELSE LocationCode END AS LocationCode
                          FROM         CO_Containers
                          WHERE     (Container = @Container) AND (Manifest = @Manifest))

UPDATE    CO_Containers SET  LocationCode = @location WHERE     (Container = @container) AND (Manifest = @manifest)

UPDATE CP_Order SET  LocationCode = @location WHERE (Container = @container) AND (Manifest = @manifest)

--if 
--(substring(@Location,1,3)= '182' OR
-- substring(@Location,1,3)= '183' OR
-- substring(@Location,1,3)= '184' OR
--  substring(@Location,1,3)= '185' )
--  or (substring(@Location,1,3) between  '906' and '945' and substring(@Location,4,1) in ('A','B','C','D','E','F','G','T') AND substring(@Location,4,1) in ('1','2','3','4','5','6'))

--  begin
		 
	update TB_Location  SET   Container= null where  Container= @container  
    update TB_Location   SET   Container= @container where    LocationCode = @location and (LocationType like '%Container%' or LocationType like '%RTG%')


-- end

--else
-- begin
--update TB_LocationTerminal  SET   Container= null where  Container= @container  
--update TB_LocationTerminal   SET   Container= @container where    LocationCode = @location 


--end

if @location <> @locationBefore
begin

insert  log
( Login_name, Form, oper, time, table_name, field_name, old_value, new_value, k1, k2, k3
)
 
SELECT     SYSTEM_USER AS Expr1, 'מלגזנים' AS Expr2, 'UPDATE' AS Expr3, GETDATE() AS Expr4, 'CO_Containers' AS Expr5, 'LocationCode' AS Expr6, 
                      RTRIM(LTRIM(@locationBefore)) AS Expr7, LocationCode, @Manifest AS Expr8, @Container AS Expr9, DealNumber
FROM         CO_Containers
WHERE     (Container = @Container) AND (Manifest = @Manifest)
end




-- the machine check if forklift discharge container before 20-05-2013
if (
SELECT     TOP (100) PERCENT COUNT(*) AS Expr1
FROM         dbo.CP_GatePassAccompany INNER JOIN
                      dbo.CP_GatePass ON dbo.CP_GatePassAccompany.DeliveryOrderNumber = 
                      dbo.CP_GatePass.DeliveryOrderNumber
WHERE     (dbo.CP_GatePassAccompany.ExitTruckID = (SELECT   EntranceTruckID     FROM  CO_Containers   
where    Container =@Container   AND  Manifest=@Manifest)) AND 
(dbo.CP_GatePass.DeliveryOrderDate > DATEADD(hour, - 2, GETDATE())))=0

begin


update  CP_TrucksConterm   set  ExitDate=getdate()  WHERE 
     TruckID =(SELECT   EntranceTruckID     FROM  CO_Containers   where    Container =@Container   AND  Manifest=@Manifest)  
AND  EntranceDate  >=(SELECT     EntranceDate  FROM  CO_Containers WHERE     (Container = @Container) AND (Manifest = @Manifest))  
AND EntryTarget1='פריקת מכולה'

end



INSERT CP_WorkType  (Container, Manifest, DealNumber, 
DealNumberSub, WorkTypeCode, Date, ToBeCharge)
   
SELECT  Container, Manifest, DealNumber, 
DealNumberSub,'03',getdate(),0 FROM CO_Containers
WHERE     (Container = @container) AND (Manifest = @manifest)


GO
