/* ===== PROC: [dbo].[sp_ForkLiftContainersNotinlistIn] ===== */


CREATE PROCEDURE [dbo].[sp_ForkLiftContainersNotinlistIn]
@containernumber char(7)  , @Terminal char(5)


AS
SELECT     dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      dbo.CO_Containers.NetoWeight AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, dbo.CO_Containers.CarrierCode AS קו, '' AS משאית, 
                      dbo.CO_Containers.RecommendedLocationCode AS [איתור צפוי], dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.WaitingTime AS המתנה, 
                      dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], dbo.CO_Containers.ContainerCapacity AS אפיון, dbo.CO_Containers.EntranceDriverID AS [ת.ז נהג], 
                      dbo.CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], dbo.TC_Client.ClientNameHe AS לקוח, dbo.CO_Containers.Manifest, 
                      CASE WHEN CO_Containers.ReserveDate IS NULL THEN '' ELSE 'מכולה שמורה' END AS נהג, dbo.CO_Containers.MarksNumbers, dbo.CO_Containers.ExitDate, 
                      dbo.CO_Containers.EntranceDate, dbo.CO_Containers.EntranceForkliftDate, dbo.CO_Containers.ExitTruckID, dbo.CO_Containers.RegisterDate, 
                      dbo.CO_Containers.UNCode1, dbo.TC_HazardousSubstances.ClassificationClassCode, dbo.CO_Containers.AVDM
FROM         dbo.CO_Containers INNER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container INNER JOIN
                      dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber LEFT OUTER JOIN
                      dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                      dbo.TC_Client ON dbo.CO_Containers.CarrierCode = dbo.TC_Client.ClientCode
WHERE     (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CO_Containers.EntranceForkliftDate IS NULL) AND 
                      (dbo.CO_ContainerProfile.ContainerNumber = @containernumber) AND (dbo.CO_Containers.Terminal = @Terminal) OR
                      (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CO_Containers.EntranceForkliftDate IS NULL) AND (dbo.CO_ContainerProfile.ContainerNumber = @containernumber) 
                      AND (dbo.CP_Deal.HandlingTypeCode = 'EM') AND (dbo.CO_Containers.RegisterDate IS NULL) AND (dbo.CO_Containers.Terminal = @Terminal)



GO
/* ===== PROC: [dbo].[sp_ForkLiftContainersNotinlistIn_APP] ===== */

 -- EXEC [dbo].[sp_ForkLiftContainersNotinlistIn_APP] @containernumber = N'%', @Terminal = N'ILHGC'
CREATE PROCEDURE [dbo].[sp_ForkLiftContainersNotinlistIn_APP]
(@ContainerNumber nvarchar(7),@Terminal char(5))


AS

SELECT top (5)   dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      dbo.CO_Containers.NetoWeight AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, dbo.CO_Containers.CarrierCode AS קו, '' AS משאית, 
                      dbo.CO_Containers.RecommendedLocationCode AS [איתור צפוי], dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.WaitingTime AS המתנה, 
                      dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], dbo.CO_Containers.ContainerCapacity AS אפיון, dbo.CO_Containers.EntranceDriverID AS [ת.ז נהג], 
                      dbo.CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], dbo.TC_Client.ClientNameHe AS לקוח, dbo.CO_Containers.Manifest, 
                      CASE WHEN CO_Containers.ReserveDate IS NULL THEN '' ELSE 'מכולה שמורה' END AS נהג, dbo.CO_Containers.MarksNumbers, dbo.CO_Containers.ExitDate, 
                      dbo.CO_Containers.EntranceDate, dbo.CO_Containers.EntranceForkliftDate, dbo.CO_Containers.ExitTruckID, dbo.CO_Containers.RegisterDate, 
                      dbo.CO_Containers.UNCode1, dbo.TC_HazardousSubstances.ClassificationClassCode, dbo.CO_Containers.AVDM
FROM         dbo.CO_Containers INNER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container INNER JOIN
                      dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber LEFT OUTER JOIN
                      dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                      dbo.TC_Client ON dbo.CO_Containers.CarrierCode = dbo.TC_Client.ClientCode
WHERE   (dbo.CO_Containers.EntranceDate IS NULL) AND
		(dbo.CO_Containers.ExitDate IS NULL) AND
         (dbo.CO_Containers.ContainerNumber LIKE @ContainerNumber) AND
		 (dbo.CO_Containers.Terminal = @Terminal) AND
         (dbo.CO_Containers.LocationCode IS NULL OR TRIM(dbo.CO_Containers.LocationCode) = '') AND 
         (dbo.CO_Containers.RegisterDate > DATEADD(m,-2,GETDATE()))



GO
