CREATE PROCEDURE [dbo].[sp_ForkLiftContainersNotinlistOut]
@containernumber char(7) , @Terminal char(5)

AS
SELECT     CO_Containers.Container AS מכולה, CO_ContainerProfile.ContainerLength AS גודל, CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      CO_Containers.NetoWeight AS משקל, CP_Deal.HandlingTypeCode AS קוד, CO_Containers.CarrierCode AS קו, '' AS משאית, 
                      CO_Containers.RecommendedLocationCode AS [איתור צפוי], CO_Containers.LocationCode AS איתור, CO_Containers.WaitingTime AS המתנה, 
                      CO_ContainerProfile.ContainerNumber AS [מספר מכולה], CO_Containers.ContainerCapacity AS אפיון, CO_Containers.EntranceDriverID AS [ת.ז נהג], 
                      CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], TC_Client.ClientNameHe AS לקוח, CO_Containers.Manifest, 
                       case when CO_Containers.ReserveDate is null then '' else 'מכולה שמורה' end  AS נהג, CO_Containers.MarksNumbers, CO_Containers.ExitDate, CO_Containers.EntranceDate, 
                      CO_Containers.ReleaseForkliftDate, CO_Containers.ExitTruckID, CO_Containers.RegisterDate, CO_Containers.UNCode1, 
                      TC_HazardousSubstances.ClassificationClassCode,CO_Containers.AVDM
FROM         TB_Drivers RIGHT OUTER JOIN
                      CO_Containers INNER JOIN
                      CO_ContainerProfile ON CO_Containers.Container = CO_ContainerProfile.Container INNER JOIN
                      CP_Deal ON CO_Containers.DealNumber = CP_Deal.DealNumber LEFT OUTER JOIN
                      TC_HazardousSubstances ON CO_Containers.UNCode1 = TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                      TC_Client ON CO_Containers.CarrierCode = TC_Client.ClientCode ON TB_Drivers.DriverID = CO_Containers.EntranceDriverID AND 
                      TB_Drivers.DriverID = CO_Containers.ExitDriverID
WHERE     (dbo.CO_Containers.Terminal = @Terminal)  AND  (CO_Containers.EntranceDate IS NOT NULL) AND (CO_ContainerProfile.ContainerNumber = @containernumber) AND 
                      (CO_Containers.ReleaseForkliftDate IS NULL) AND (CO_Containers.ExitDate IS NULL) OR
                      (CO_ContainerProfile.ContainerNumber = @containernumber) AND (CO_Containers.ReleaseForkliftDate IS NULL) AND (CO_Containers.ExitDate IS NULL)
                       AND (CP_Deal.HandlingTypeCode = 'EM') AND (CO_Containers.RegisterDate IS NULL)

GO
