/* ===== PROC: [dbo].[sp_ForkLiftContainersOut_App] ===== */


Create PROCEDURE [dbo].[sp_ForkLiftContainersOut_App]

@Terminal char(5),
@Em nvarchar(10)
AS 


SELECT     TOP (100) PERCENT dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      dbo.CO_Containers.NetoWeight AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד, RTRIM(dbo.CO_Containers.CarrierCode) AS קו, 
                      CASE WHEN TB_Trucks.EquipmentNumber IS NULL THEN ExitTruckID ELSE TB_Trucks.EquipmentNumber END AS משאית, dbo.CO_Containers.LocationCode AS איתור, 
                      dbo.CO_Containers.WaittingTimeExitDate AS המתנה, dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], dbo.CO_Containers.ContainerCapacity AS אפיון, 
                      dbo.CO_Containers.EntranceDriverID AS [ת.ז נהג], dbo.CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], dbo.TC_Client.ClientNameHe AS לקוח, 
                      dbo.CO_Containers.Manifest, dbo.CO_Containers.DealNumber, dbo.CO_Containers.DealNumberSub, dbo.CO_Containers.EntranceDate, 
                      dbo.CO_Containers.ReleaseForkliftDate, dbo.CO_Containers.MarksNumbers, dbo.CO_Containers.ExitGAteDate, dbo.CO_Containers.DestinationDesc, 
                      dbo.CO_Containers.ReflectOrderDate, dbo.TC_HazardousSubstances.ClassificationClass AS UN, dbo.CO_Containers.AVDM , 0 as reflect
FROM         dbo.CO_Containers INNER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container INNER JOIN
                      dbo.TB_Trucks ON dbo.CO_Containers.ExitTruckID = dbo.TB_Trucks.TruckID INNER JOIN
                      dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber LEFT OUTER JOIN
                      dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                      dbo.TC_Client ON dbo.CO_Containers.CarrierCode = dbo.TC_Client.ClientCode
WHERE     ((dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitDate IS NOT NULL) AND (dbo.CO_Containers.ReleaseForkliftDate IS NULL) AND 
                      (dbo.CO_Containers.ExitGAteDate IS NULL) AND (dbo.CO_Containers.DestinationDesc <> 'קונטרם') AND (dbo.CO_Containers.WaittingTimeExitDate < 1000) AND 
                      (dbo.CO_Containers.ExitTruckFirst <> '0') AND (dbo.CO_Containers.ReserveDate IS NULL) AND (dbo.CP_Deal.HandlingTypeCode <> 'DP') 
					  AND (dbo.CO_Containers.Terminal = @Terminal))
					  and (@Em <> 'Empty' or CP_Deal.HandlingTypeCode = 'EM')

UNION ALL

SELECT        TOP (100) PERCENT dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, dbo.CO_Containers.NetoWeight AS משקל, 
                         dbo.CP_Deal.HandlingTypeCode AS קוד, RTRIM(dbo.CO_Containers.CarrierCode) AS קו, CASE WHEN TB_Trucks.EquipmentNumber IS NULL 
                         THEN CO_ContainersReflect.ReflectExitTruckID ELSE TB_Trucks.EquipmentNumber END AS משאית, dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.WaittingTimeExitDate AS המתנה, 
                         dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], dbo.CO_Containers.ContainerCapacity AS אפיון, dbo.CO_Containers.EntranceDriverID AS [ת.ז נהג], dbo.CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], 
                         dbo.TC_Client.ClientNameHe AS לקוח, dbo.CO_Containers.Manifest, dbo.CO_Containers.DealNumber, dbo.CO_Containers.DealNumberSub, dbo.CO_Containers.EntranceDate, dbo.CO_Containers.ReleaseForkliftDate, 
                         dbo.CO_Containers.MarksNumbers, dbo.CO_Containers.ExitGAteDate, dbo.CO_Containers.DestinationDesc, dbo.CO_Containers.ReflectOrderDate, dbo.TC_HazardousSubstances.ClassificationClass AS UN, 
                         dbo.CO_Containers.AVDM, 1 AS reflect
FROM            dbo.CO_Containers INNER JOIN
                         dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber INNER JOIN
                         dbo.CO_ContainersReflect ON dbo.CO_ContainersReflect.Container = dbo.CO_Containers.Container AND dbo.CO_ContainersReflect.Manifest = dbo.CO_Containers.Manifest INNER JOIN
                         dbo.V_MaxReflectOrderDate ON dbo.V_MaxReflectOrderDate.Container = dbo.CO_ContainersReflect.Container AND dbo.V_MaxReflectOrderDate.Manifest = dbo.CO_ContainersReflect.Manifest AND 
                         dbo.V_MaxReflectOrderDate.MAXReflectOrderDate = dbo.CO_ContainersReflect.ReflectOrderDate INNER JOIN
                         dbo.TB_Trucks ON dbo.CO_ContainersReflect.ReflectExitTruckID = dbo.TB_Trucks.TruckID LEFT OUTER JOIN
                         dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container LEFT OUTER JOIN
                         dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                         dbo.TC_Client ON dbo.CO_Containers.CarrierCode = dbo.TC_Client.ClientCode
WHERE        ((dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ReleaseForkliftDate IS NULL) AND (dbo.CO_Containers.ExitGAteDate IS NULL) AND (dbo.CO_Containers.DestinationDesc <> 'קונטרם') AND 
                         (dbo.CO_Containers.ReserveDate IS NULL) AND (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND (dbo.CO_Containers.Terminal = @Terminal) AND (dbo.CO_Containers.ReturnFromReflectDate = CONVERT(DATETIME, 
                         '1900-01-01 00:00:00', 102)) AND (dbo.CO_ContainersReflect.ExitToReflectDate IS NOT NULL) AND (SUBSTRING(dbo.CO_ContainersReflect.ReflectExitTruckID, 1, 1) <> '0'))
					  and (@Em <> 'Empty' or CP_Deal.HandlingTypeCode = 'EM')

UNION ALL

SELECT        TOP (100) PERCENT dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, dbo.CO_Containers.NetoWeight AS משקל, 
                         dbo.CP_Deal.HandlingTypeCode AS קוד, RTRIM(dbo.CO_Containers.CarrierCode) AS קו, CASE WHEN TB_Trucks.EquipmentNumber IS NULL THEN MarlogExitTruckID ELSE TB_Trucks.EquipmentNumber END AS משאית, 
                         dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.WaittingTimeExitDate AS המתנה, dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], dbo.CO_Containers.ContainerCapacity AS אפיון, 
                         dbo.CO_Containers.MarlogExitDriverID AS [ת.ז נהג], dbo.CO_Containers.MarlogTruckCompanyCode AS [חברת הובלה], dbo.TC_Client.ClientNameHe AS לקוח, dbo.CO_Containers.Manifest, dbo.CO_Containers.DealNumber, 
                         dbo.CO_Containers.DealNumberSub, dbo.CO_Containers.EntranceDate, dbo.CO_Containers.ReleaseForkliftDate, dbo.CO_Containers.MarksNumbers, dbo.CO_Containers.ExitGAteDate, dbo.CO_Containers.DestinationDesc, 
                         dbo.CO_Containers.ReflectOrderDate, dbo.TC_HazardousSubstances.ClassificationClass AS UN, dbo.CO_Containers.AVDM, 0 AS reflect
FROM            dbo.CO_Containers INNER JOIN
                         dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container INNER JOIN
                         dbo.TB_Trucks ON dbo.CO_Containers.MarlogExitTruckID = dbo.TB_Trucks.TruckID INNER JOIN
                         dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber LEFT OUTER JOIN
                         dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                         dbo.TC_Client ON dbo.CO_Containers.CarrierCode = dbo.TC_Client.ClientCode
WHERE        ((dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ReleaseForkliftDate IS NULL) AND (dbo.CO_Containers.ExitGAteDate IS NULL) AND (dbo.CO_Containers.DestinationDesc <> 'קונטרם') AND 
                         (dbo.CO_Containers.ReserveDate IS NULL) AND (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND (dbo.CO_Containers.Terminal= @Terminal) AND (dbo.CO_Containers.ExitDate IS NULL) AND 
                         (dbo.CO_Containers.ExitToMarlogDate IS NOT NULL) AND (dbo.CO_Containers.ReturnFromMarlogDate IS NULL))
					  and (@Em <> 'Empty' or CP_Deal.HandlingTypeCode = 'EM')

ORDER BY המתנה DESC


/*



SELECT     TOP (100) PERCENT dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      dbo.CO_Containers.NetoWeight AS משקל, dbo.CP_Deal.HandlingTypeCode AS קוד,RTRIM(dbo.CO_Containers.CarrierCode) AS קו, 
                      CASE WHEN TB_Trucks.EquipmentNumber IS NULL THEN ReflectExitTruckID ELSE TB_Trucks.EquipmentNumber END AS משאית, 
                      dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.WaittingTimeExitDate AS המתנה, dbo.CO_ContainerProfile.ContainerNumber AS [מספר מכולה], 
                      dbo.CO_Containers.ContainerCapacity AS אפיון, dbo.CO_Containers.EntranceDriverID AS [ת.ז נהג], dbo.CO_Containers.EntranceTruckCompanyCode AS [חברת הובלה], 
                      dbo.TC_Client.ClientNameHe AS לקוח, dbo.CO_Containers.Manifest, dbo.CO_Containers.DealNumber, dbo.CO_Containers.DealNumberSub, 
                      dbo.CO_Containers.EntranceDate, dbo.CO_Containers.ReleaseForkliftDate, dbo.CO_Containers.MarksNumbers, dbo.CO_Containers.ExitGAteDate, 
                      dbo.CO_Containers.DestinationDesc, dbo.CO_Containers.ReflectOrderDate, dbo.TC_HazardousSubstances.ClassificationClass AS UN, dbo.CO_Containers.AVDM  , 1 as reflect
FROM         dbo.CO_Containers INNER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container INNER JOIN
                      dbo.TB_Trucks ON dbo.CO_Containers.ReflectExitTruckID = dbo.TB_Trucks.TruckID INNER JOIN
                      dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber LEFT OUTER JOIN
                      dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                      dbo.TC_Client ON dbo.CO_Containers.CarrierCode = dbo.TC_Client.ClientCode
WHERE     (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ReleaseForkliftDate IS NULL) AND (dbo.CO_Containers.ExitGAteDate IS NULL) AND 
                      (dbo.CO_Containers.DestinationDesc <> 'קונטרם') AND (dbo.CO_Containers.ReserveDate IS NULL) AND (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND 
                      (dbo.CO_Containers.Terminal = @Terminal) AND (ReflectExitTruckFirst <> '0') AND (dbo.CO_Containers.ExitToReflectDate IS NOT NULL) AND 
                      (dbo.CO_Containers.ReturnFromReflectDate = CONVERT(DATETIME, '1900-01-01 00:00:00', 102))
ORDER BY המתנה DESC

*/



