/* ===== PROC: [dbo].[sp_ForkLiftContainersOutUpDate] ===== */


CREATE  PROCEDURE  [dbo].[sp_ForkLiftContainersOutUpDate] 
@container char(11),
@manifest char(6) ,
@exitforkliftoperatorID char(10),
@exitforkliftID char(7),
@releaseforkliftDate datetime

AS
UPDATE    CO_Containers
SET       ExitForkliftOperatorID = @exitforkliftoperatorID, ExitForkliftNumber = @exitforkliftID, ReleaseForkliftDate = getdate()
WHERE     (Container = @container) AND (Manifest = @manifest)

