/* ===== PROC: [dbo].[sp_ForkliftContainerTypeCombo] ===== */


CREATE PROCEDURE [dbo].[sp_ForkliftContainerTypeCombo]

AS
SELECT  ContainerTypeCode FROM dbo.TC_ContainerType WHERE  (ContainerConterm = 1)
GO
/* ===== PROC: [dbo].[sp_ForkliftCustomersCombo] ===== */


CREATE PROCEDURE [dbo].[sp_ForkliftCustomersCombo]
@Terminal char(5)
AS
SELECT  distinct  trim(TC_Client.ShortClientName) AS ClientName,TC_Client.ClientCode ClientCode
FROM         TC_Client INNER JOIN
                      CP_Deal ON TC_Client.ClientCode = CP_Deal.RecieveCommisionCode RIGHT OUTER JOIN
                      CO_Containers INNER JOIN
                      CO_ContainerProfile ON CO_Containers.Container = CO_ContainerProfile.Container LEFT OUTER JOIN
                      TC_Client AS TC_Client_1 ON CO_Containers.ShipAgentCode = TC_Client_1.ClientCode ON CP_Deal.DealNumber = CO_Containers.DealNumber
WHERE    (dbo.CO_Containers.Terminal = @Terminal)  AND  (CO_Containers.ExitDate IS NULL) AND (CP_Deal.HandlingTypeCode = 'HH' OR
                      CP_Deal.HandlingTypeCode = 'PP' OR
                     
                      CP_Deal.HandlingTypeCode = 'FR' OR
                      CP_Deal.HandlingTypeCode = 'EX') AND (CO_Containers.EntranceDate IS NULL) AND (CO_Containers.RegisterDate > GETDATE() - 7)
					  order by trim(TC_Client.ShortClientName)


GO
/* ===== PROC: [dbo].[sp_ForkliftDamage] ===== */


CREATE  PROCEDURE [dbo].[sp_ForkliftDamage]
	(@container char(11),
	 @manifest char(6))
AS
SELECT     TB_Damage.DamageDescHe, TB_LocationDamage.LocationDamageDesc, CO_Containers.Container, CO_Containers.Manifest, CP_Damages.Comments
FROM         CO_Containers INNER JOIN
                      CP_Damages ON CO_Containers.Container = CP_Damages.Container AND CO_Containers.Manifest = CP_Damages.Manifest INNER JOIN
                      TB_Damage ON CP_Damages.DamageCode = TB_Damage.DamageCode LEFT OUTER JOIN
                      TB_LocationDamage ON CP_Damages.LocationDamageCode = TB_LocationDamage.LocationDamageCode
WHERE     (CO_Containers.Container = @container) AND (CO_Containers.Manifest = @manifest)


GO
/* ===== PROC: [dbo].[sp_ForkLiftEmptyLoction] ===== */




CREATE PROCEDURE [dbo].[sp_ForkLiftEmptyLoction]

@Terminal char(5)
AS
SELECT     CO_Containers.Container AS מכולה, CO_Containers.EntranceDate AS [תאריך כניסה בשער], CP_Deal.HandlingTypeCode AS [קוד טיפול], 
                      CO_Containers.CarrierCode AS [קו ספנות], CO_Containers.LocationCode, CO_Containers.ExitDate, CO_Containers.DealNumber, 
                      CO_Containers.DealNumberSub, CO_Containers.Manifest
FROM         CO_Containers INNER JOIN
                      CP_Deal ON CO_Containers.DealNumber = CP_Deal.DealNumber
WHERE    (dbo.CO_Containers.Terminal=@Terminal AND     (CO_Containers.EntranceDate IS NOT NULL AND CO_Containers.EntranceDate >= CONVERT(DATETIME, '2011-01-01 00:00:00', 102)) AND 
                      (CO_Containers.ExitDate IS NULL) AND (CO_Containers.LocationCode IS NULL))
					  and CP_Deal.HandlingTypeCode  <> 'MG'


GO
