/* ===== PROC: [dbo].[sp_ForkLiftExpectedContainers] ===== */


CREATE PROCEDURE [dbo].[sp_ForkLiftExpectedContainers]
@Terminal char(5)

AS

SELECT    CO_Containers.Container AS מכולה, CO_ContainerProfile.ContainerLength AS גודל, CO_ContainerProfile.ContainerTypeCode AS סוג, 
          CP_Deal.HandlingTypeCode AS טיפול, CO_Containers.RecommendedLocationCode AS [איתור צפוי], TC_Client.ShortClientName AS לקוח, 
          RTRIM(LTRIM(dbo.CO_Containers.CarrierCode)) AS [קו], CO_Containers.RegisterDate AS [תאריך שידור],
		  CO_Containers.Manifest AS מצהר, CO_Containers.DealNumber AS עסקה,  CO_Containers.DealNumberSub AS סידורי
FROM      TC_Client INNER JOIN
          CP_Deal ON TC_Client.ClientCode = CP_Deal.RecieveCommisionCode RIGHT OUTER JOIN
          CO_Containers INNER JOIN
          CO_ContainerProfile ON CO_Containers.Container = CO_ContainerProfile.Container LEFT OUTER JOIN
          TC_Client AS TC_Client_1 ON CO_Containers.ShipAgentCode = TC_Client_1.ClientCode ON CP_Deal.DealNumber = CO_Containers.DealNumber
WHERE    (dbo.CO_Containers.Terminal = @Terminal)  
AND      (CO_Containers.ExitDate IS NULL) 
AND      (CP_Deal.HandlingTypeCode = 'HH' OR CP_Deal.HandlingTypeCode = 'PP' OR CP_Deal.HandlingTypeCode = 'FR' OR CP_Deal.HandlingTypeCode = 'EX') 
AND      (CO_Containers.EntranceDate IS NULL) 
AND      (CO_Containers.RegisterDate > GETDATE() - 7)

GO
/* ===== PROC: [dbo].[sp_ForkLiftExpectedForLoction] ===== */

CREATE PROCEDURE [dbo].[sp_ForkLiftExpectedForLoction]

 @LocationCode char(10)  , @Terminal char(5)
AS
	SELECT COUNT(Container) AS Counter
	FROM   CO_Containers
	WHERE  (ExitDate IS NOT NULL) AND (LocationCode = @locationCode) AND (Terminal = @Terminal)



GO
/* ===== PROC: [dbo].[sp_ForkLiftFInForLoction] ===== */





CREATE PROCEDURE [dbo].[sp_ForkLiftFInForLoction] 
@LocationCode char(10)  ,@Terminal char(5)
AS
	SELECT COUNT(Container) AS CounterIn
	FROM   CO_Containers
	WHERE  (Terminal = @Terminal) AND 
                (ExitDate IS NULL) AND (LocationCode = @locationCode) AND (EntranceDate IS NOT NULL)


GO
/* ===== PROC: [dbo].[sp_ForkLiftForAreaLoctionConts] ===== */




CREATE PROCEDURE [dbo].[sp_ForkLiftForAreaLoctionConts]
	@LocationCode Varchar(10)  , @Terminal char(5)
AS
BEGIN
SELECT     TOP (100) PERCENT dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, dbo.CP_Deal.HandlingTypeCode AS סוג, 
                      dbo.CO_Containers.EntranceDate AS [תאריך כניסה], dbo.TC_HazardousSubstances.ClassificationClassCode AS חומס, dbo.CO_Containers.LocationCode AS איתור
FROM         dbo.CO_Containers INNER JOIN
                      dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container INNER JOIN
                      dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber LEFT OUTER JOIN
                      dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode
WHERE   (dbo.CO_Containers.Terminal = @Terminal) AND     (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CO_Containers.LocationCode LIKE @LocationCode  OR
                                                    dbo.CO_Containers.LocationCode LIKE @LocationCode + 'A%' OR
                                                    dbo.CO_Containers.LocationCode LIKE @LocationCode + 'B%' OR
                                                    dbo.CO_Containers.LocationCode LIKE @LocationCode + 'C%' OR
                                                    dbo.CO_Containers.LocationCode LIKE @LocationCode + 'D%' OR
                                                    dbo.CO_Containers.LocationCode LIKE @LocationCode + 'E%' OR
                                                    dbo.CO_Containers.LocationCode LIKE @LocationCode + 'G%')

 AND (dbo.CO_Containers.EntranceDate IS NOT NULL)
ORDER BY איתור

END

GO
