/* ===== PROC: [dbo].[sp_ForkLiftGetContainers] ===== */


CREATE PROCEDURE [dbo].[sp_ForkLiftGetContainers]
(@ContainerNumber char(7),@Terminal char(5))
AS 



SELECT        dbo.CO_Containers.Container
FROM            dbo.CO_Containers INNER JOIN
                         dbo.CO_ContainerProfile ON dbo.CO_Containers.Container = dbo.CO_ContainerProfile.Container LEFT OUTER JOIN
                         dbo.TC_HazardousSubstances ON dbo.CO_Containers.UNCode1 = dbo.TC_HazardousSubstances.UNCode LEFT OUTER JOIN
                         dbo.TB_WorkType INNER JOIN
                         dbo.CP_Order ON dbo.TB_WorkType.WorkTypeCode = dbo.CP_Order.WorkTypeCode ON dbo.CO_Containers.Container = dbo.CP_Order.Container AND dbo.CO_Containers.Manifest = dbo.CP_Order.Manifest LEFT OUTER JOIN
                         dbo.CP_Deal INNER JOIN
                         dbo.TC_Client ON dbo.CP_Deal.RecieveCommisionCode = dbo.TC_Client.ClientCode ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber
WHERE        (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND (dbo.CO_Containers.Terminal = @Terminal) AND 
                         (dbo.CO_ContainerProfile.ContainerNumber LIKE @ContainerNumber) OR
                         (dbo.CO_Containers.ExitDate IS NULL) AND (dbo.CP_Deal.HandlingTypeCode <> 'EM') AND (dbo.CO_Containers.Terminal = @Terminal) AND (dbo.CP_Deal.HandlingTypeCode <> 'DP') AND (dbo.CP_Deal.HandlingTypeCode <> 'CL') 
                         AND (dbo.CO_Containers.RegisterDate IS NOT NULL) AND (dbo.CO_ContainerProfile.ContainerNumber LIKE @ContainerNumber)

UNION
SELECT ''
ORDER BY dbo.CO_Containers.Container
GO
/* ===== PROC: [dbo].[sp_ForkliftHazardousSubstances] ===== */



CREATE  PROCEDURE [dbo].[sp_ForkliftHazardousSubstances]
AS
SELECT     TC_HazardousSubstances.ClassificationClassCode
FROM         TC_HazardousSubstances INNER JOIN
                      CO_Containers ON TC_HazardousSubstances.UNCode = CO_Containers.UNCode1
WHERE     (CO_Containers.EntranceDate IS NOT NULL) AND (CO_Containers.ExitDate IS NULL)
GROUP BY TC_HazardousSubstances.ClassificationClassCode
ORDER BY TC_HazardousSubstances.ClassificationClassCode
--HAVING      (COUNT(CO_Containers.Container) >= 10)


GO
/* ===== PROC: [dbo].[sp_ForkLiftInOutDiory] ===== */



CREATE PROCEDURE [dbo].[sp_ForkLiftInOutDiory]
@Terminal char(5)
AS
select top 100 * from (
SELECT     dbo.CO_Containers.EntranceForkliftDate AS תאריך, 'כניסה' AS תנועה, dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, 
                      dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, dbo.CP_Deal.HandlingTypeCode AS טיפול, dbo.HR_Emp.EmpName AS מלגזן, 
                      dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.EntranceForkliftNumber AS מלגזה
FROM         dbo.CO_ContainerProfile INNER JOIN
                      dbo.CO_Containers ON dbo.CO_ContainerProfile.Container = dbo.CO_Containers.Container INNER JOIN
                      dbo.HR_Emp ON dbo.CO_Containers.EntranceForkliftOperatorID = dbo.HR_Emp.EmpID RIGHT OUTER JOIN
                      dbo.TB_Drivers ON dbo.CO_Containers.EntranceDriverID = dbo.TB_Drivers.DriverID LEFT OUTER JOIN
                      dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber
WHERE  dbo.CO_Containers.Terminal=N''+@Terminal+'' AND    (dbo.CO_Containers.EntranceForkliftDate >= GETDATE() - 7) AND (dbo.CO_Containers.EntranceForkliftDate <= GETDATE())


UNION ALL
 


SELECT     TOP (100) PERCENT CO_Containers_1.ReleaseForkliftDate AS תאריך, 'יציאה' AS תנועה, CO_Containers_1.Container AS מכולה, 
                      CO_ContainerProfile_1.ContainerLength AS גודל, CO_ContainerProfile_1.ContainerTypeCode AS סוג, CP_Deal_1.HandlingTypeCode AS טיפול, 
                      dbo.HR_Emp.EmpName AS מלגזן, CO_Containers_1.LoadPortCode AS איתור, CO_Containers_1.ExitForkliftNumber AS מלגזה
FROM         dbo.CO_ContainerProfile AS CO_ContainerProfile_1 INNER JOIN
                      dbo.CO_Containers AS CO_Containers_1 ON CO_ContainerProfile_1.Container = CO_Containers_1.Container INNER JOIN
                      dbo.HR_Emp ON CO_Containers_1.ExitForkliftOperatorID = dbo.HR_Emp.EmpID RIGHT OUTER JOIN
                      dbo.TB_Drivers AS TB_Drivers_1 ON CO_Containers_1.EntranceDriverID = TB_Drivers_1.DriverID LEFT OUTER JOIN
                      dbo.CP_Deal AS CP_Deal_1 ON CO_Containers_1.DealNumber = CP_Deal_1.DealNumber
WHERE  CO_Containers_1.Terminal=N''+@Terminal+'' AND   (CO_Containers_1.ReleaseForkliftDate >= GETDATE() - 7) AND (CO_Containers_1.ReleaseForkliftDate <= GETDATE())
) a
ORDER BY 'תאריך' DESC
GO
/* ===== PROC: [dbo].[sp_ForkLiftInOutDiory_App] ===== */



CREATE PROCEDURE [dbo].[sp_ForkLiftInOutDiory_App]
@Terminal char(5),
@ToDate datetime
AS
select top 100 * from (
SELECT     dbo.CO_Containers.EntranceForkliftDate AS תאריך, 'כניסה' AS תנועה, dbo.CO_Containers.Container AS מכולה, dbo.CO_ContainerProfile.ContainerLength AS גודל, 
                      dbo.CO_ContainerProfile.ContainerTypeCode AS סוג, dbo.CP_Deal.HandlingTypeCode AS טיפול, dbo.HR_Emp.EmpName AS מלגזן, 
                      dbo.CO_Containers.LocationCode AS איתור, dbo.CO_Containers.EntranceForkliftNumber AS מלגזה
FROM         dbo.CO_ContainerProfile INNER JOIN
                      dbo.CO_Containers ON dbo.CO_ContainerProfile.Container = dbo.CO_Containers.Container INNER JOIN
                      dbo.HR_Emp ON dbo.CO_Containers.EntranceForkliftOperatorID = dbo.HR_Emp.EmpID RIGHT OUTER JOIN
                      dbo.TB_Drivers ON dbo.CO_Containers.EntranceDriverID = dbo.TB_Drivers.DriverID LEFT OUTER JOIN
                      dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber
WHERE  dbo.CO_Containers.Terminal=N''+@Terminal+'' AND    (dbo.CO_Containers.EntranceForkliftDate >= @ToDate ) AND (dbo.CO_Containers.EntranceForkliftDate <= @ToDate + 1)


UNION ALL
 


SELECT    CO_Containers_1.ReleaseForkliftDate AS תאריך, 'יציאה' AS תנועה, CO_Containers_1.Container AS מכולה, 
                      CO_ContainerProfile_1.ContainerLength AS גודל, CO_ContainerProfile_1.ContainerTypeCode AS סוג, CP_Deal_1.HandlingTypeCode AS טיפול, 
                      dbo.HR_Emp.EmpName AS מלגזן, CO_Containers_1.LoadPortCode AS איתור, CO_Containers_1.ExitForkliftNumber AS מלגזה
FROM         dbo.CO_ContainerProfile AS CO_ContainerProfile_1 INNER JOIN
                      dbo.CO_Containers AS CO_Containers_1 ON CO_ContainerProfile_1.Container = CO_Containers_1.Container INNER JOIN
                      dbo.HR_Emp ON CO_Containers_1.ExitForkliftOperatorID = dbo.HR_Emp.EmpID RIGHT OUTER JOIN
                      dbo.TB_Drivers AS TB_Drivers_1 ON CO_Containers_1.EntranceDriverID = TB_Drivers_1.DriverID LEFT OUTER JOIN
                      dbo.CP_Deal AS CP_Deal_1 ON CO_Containers_1.DealNumber = CP_Deal_1.DealNumber
WHERE  CO_Containers_1.Terminal=N''+@Terminal+'' AND   (CO_Containers_1.ReleaseForkliftDate >= @ToDate) AND (CO_Containers_1.ReleaseForkliftDate <= @ToDate+1)
) a
ORDER BY 'תאריך' DESC

GO
