/* ===== PROC: [dbo].[sp_ForkLiftRecommendedLocation] ===== */


CREATE PROCEDURE [dbo].[sp_ForkLiftRecommendedLocation]
@Terminal char(5)

AS
SELECT     dbo.TB_RecommendedLocation.ClientCode + dbo.TC_Client.ShortClientName as [לקוח], dbo.TB_RecommendedLocation.ContainerLength as [גודל], 
                      dbo.TB_RecommendedLocation.ContainerTypeCode as [סוג],  dbo.TB_RecommendedLocation.CarrierCode as [ספנות], 
                      dbo.TB_RecommendedLocation.RecommendedLocationCode as [א מומלץ]
FROM         dbo.TB_RecommendedLocation INNER JOIN
                      dbo.TC_Client ON dbo.TB_RecommendedLocation.ClientCode = dbo.TC_Client.ClientCode
WHERE    (dbo.TB_RecommendedLocation.Terminal = @Terminal) AND    (dbo.TB_RecommendedLocation.HandlingTypeCode = 'EM')
