/* ===== PROC: [dbo].[sp_ForkliftShipingLinesCombo] ===== */


CREATE PROCEDURE [dbo].[sp_ForkliftShipingLinesCombo]
@Terminal char(5)
AS
SELECT     TOP (100) PERCENT RTRIM(LTRIM(dbo.CO_Containers.CarrierCode)) AS CarrierCode, dbo.TC_Client.ClientName, dbo.TC_Client.ClientNameHe
FROM         dbo.CO_Containers INNER JOIN
                      dbo.CP_Deal ON dbo.CO_Containers.DealNumber = dbo.CP_Deal.DealNumber INNER JOIN
                      dbo.TC_Client ON dbo.CO_Containers.CarrierCode = dbo.TC_Client.ClientCode
WHERE    (dbo.CO_Containers.Terminal = @Terminal)  AND   (dbo.CP_Deal.HandlingTypeCode = 'EM') AND (dbo.CO_Containers.EntranceDate IS NOT NULL) AND (dbo.CO_Containers.ExitDate IS NULL)
GROUP BY dbo.CO_Containers.CarrierCode, dbo.TC_Client.ClientName, dbo.TC_Client.ClientNameHe
HAVING      (dbo.TC_Client.ClientName IS NOT NULL) AND (RTRIM(LTRIM(dbo.CO_Containers.CarrierCode)) <> 'CSV')
ORDER BY CarrierCode
GO
