/* ===== PROC: [dbo].[sp_ForkliftUnCodes] ===== */



create  PROCEDURE [dbo].[sp_ForkliftUnCodes]
AS
SELECT  distinct   CO_Containers.UNCode1 UNCode
FROM       CO_Containers 
WHERE     (CO_Containers.EntranceDate IS NOT NULL) AND (CO_Containers.ExitDate IS NULL) and len(trim(uncode1))=4
union 
SELECT  distinct   CO_Containers.UNCode2 UNCode
FROM       CO_Containers 
WHERE     (CO_Containers.EntranceDate IS NOT NULL) AND (CO_Containers.ExitDate IS NULL) and len(trim(uncode2))=4
union
SELECT  distinct   CO_Containers.UNCode3 UNCode
FROM       CO_Containers 
WHERE     (CO_Containers.EntranceDate IS NOT NULL) AND (CO_Containers.ExitDate IS NULL) and len(trim(uncode3))=4
union 
SELECT  distinct   CO_Containers.UNCode4 UNCode
FROM       CO_Containers 
WHERE     (CO_Containers.EntranceDate IS NOT NULL) AND (CO_Containers.ExitDate IS NULL)  and len(trim(uncode4))=4



GO
