/* ===== PROC: [dbo].[sp_ForkLiftWorkDone] ===== */


CREATE  PROCEDURE [dbo].[sp_ForkLiftWorkDone]
	@container char(11),
	@manifest char(6),
	@WorkTypeCode char(2),
	@LoginName char(10),
	@workDone  bit
AS
	UPDATE    CP_Order
	SET       ForkliftDone = @workDone, ForkliftUpdateLoginName = @LoginName
	WHERE     (Container = @container) AND (Manifest = @manifest) AND (WorkTypeCode = @WorkTypeCode)

GO
/* ===== PROC: [dbo].[sp_ForkLiftWorks] ===== */


CREATE PROCEDURE [dbo].[sp_ForkLiftWorks]
@Terminal char(5)
AS
SELECT     CP_Order.Container AS מכולה, CO_ContainerProfile.ContainerLength AS גו, CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      CO_Containers.NetoWeight AS משקל, CO_Containers.LocationCode AS איתור, CP_Order.TargetDate AS לתאריך, 
                      TB_WorkType.WorkTypeDesc AS [סוג עבודה], CP_Order.ForkliftDone AS בוצע, CP_Order.Comment AS הערות, ExaminTestType as [סוג הבדיקה], TB_WorkType.WorkTypeCode, 
                      CP_Order.DealNumber, CP_Order.DealNumberSub, CP_Order.Manifest, CONVERT(smalldatetime,CONVERT(varchar,CP_Order.TargetDate,111)) AS date1
FROM         CP_Order INNER JOIN
                      TB_WorkType ON CP_Order.WorkTypeCode = TB_WorkType.WorkTypeCode INNER JOIN
                      CO_ContainerProfile ON CP_Order.Container = CO_ContainerProfile.Container INNER JOIN
                      CO_Containers ON CP_Order.Container = CO_Containers.Container AND CP_Order.Manifest = CO_Containers.Manifest
WHERE    (dbo.CO_Containers.Terminal = @Terminal)  AND  (CP_Order.PerformCode = 0) AND (TB_WorkType.ForkLiftUse = 1) AND (CO_Containers.ExitDate IS NULL) OR
      (dbo.CO_Containers.Terminal = @Terminal)  AND   (CP_Order.PerformCode = 0) AND (TB_WorkType.ForkLiftUse = 2) AND (CO_Containers.ExitDate IS NULL)


GO
/* ===== PROC: [dbo].[sp_ForkLiftWorksByDate] ===== */




CREATE PROCEDURE [dbo].[sp_ForkLiftWorksByDate]
@targetdate smalldatetime , @Terminal char(5)
AS
SELECT     CP_Order.Container AS מכולה, CO_ContainerProfile.ContainerLength AS גודל, CO_ContainerProfile.ContainerTypeCode AS סוג, 
                      CO_Containers.NetoWeight AS משקל, CO_Containers.LocationCode AS איתור, CAST(SUBSTRING(CAST(CP_Order.TargetDate AS char(12)), 1, 12) 
                      AS smalldatetime) AS לתאריך, TB_WorkType.WorkTypeDesc AS [סוג עבודה], CP_Order.Comment AS הערות, CP_Order.PerformCode
FROM         CP_Order INNER JOIN
                      TB_WorkType ON CP_Order.WorkTypeCode = TB_WorkType.WorkTypeCode INNER JOIN
                      CO_ContainerProfile ON CP_Order.Container = CO_ContainerProfile.Container INNER JOIN
                      CO_Containers ON CP_Order.Container = CO_Containers.Container AND CP_Order.Manifest = CO_Containers.Manifest
WHERE    (dbo.CO_Containers.Terminal = @Terminal)  AND   (CONVERT(smalldatetime, LEFT(CAST(CP_Order.TargetDate AS char(12)), 12), 103) = @targetdate)




GO
/* ===== PROC: [dbo].[sp_ForkliftWorksCombo] ===== */




CREATE  PROCEDURE [dbo].[sp_ForkliftWorksCombo]
AS
SELECT     TB_WorkType.WorkTypeCode, TB_WorkType.WorkTypeDesc
FROM         TB_WorkType INNER JOIN
                      CP_Order ON TB_WorkType.WorkTypeCode = CP_Order.WorkTypeCode
WHERE     (TB_WorkType.ForkLiftUse = 1) AND (CP_Order.PerformCode = 0) OR
                      (TB_WorkType.ForkLiftUse = 2) AND (CP_Order.PerformCode = 0)
GROUP BY TB_WorkType.WorkTypeCode, TB_WorkType.WorkTypeDesc




GO
/* ===== PROC: [dbo].[sp_ForkLiftWorksForContainer] ===== */





CREATE  PROCEDURE [dbo].[sp_ForkLiftWorksForContainer]
@dealnumber char(16),
@subdealnumber char(5)
AS
SELECT     TB_WorkType.WorkTypeDesc, CP_Order.PerformCode
FROM         CP_Order INNER JOIN
                      TB_WorkType ON CP_Order.WorkTypeCode = TB_WorkType.WorkTypeCode
WHERE     (CP_Order.DealNumber = @dealnumber) AND (CP_Order.DealNumberSub = @subdealnumber) AND (CP_Order.PerformCode = 0)
ORDER BY CP_Order.TargetDate


GO
/* ===== PROC: [dbo].[sp_ForkLiftWorksUpdate] ===== */


CREATE  PROCEDURE [dbo].[sp_ForkLiftWorksUpdate]
	@container char(11),
	@manifest char(6) 
AS
	UPDATE    CP_Order
	SET       ForkliftDone = 1
	WHERE     (Container = @container) AND (Manifest = @manifest)

GO

